PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE IF NOT EXISTS "d1_migrations"(
		id         INTEGER PRIMARY KEY AUTOINCREMENT,
		name       TEXT UNIQUE,
		applied_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL
);
CREATE TABLE users (
  id TEXT PRIMARY KEY,
  username TEXT NOT NULL COLLATE NOCASE UNIQUE,
  password_hash TEXT NOT NULL,
  display_name TEXT NOT NULL,
  bio TEXT NOT NULL DEFAULT '',
  role TEXT NOT NULL DEFAULT 'USER' CHECK (role IN ('USER', 'ADMIN', 'COOPERATOR')),
  level INTEGER NOT NULL DEFAULT 0,
  device_hash TEXT NOT NULL UNIQUE,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
, public_id INTEGER, status TEXT NOT NULL DEFAULT 'ACTIVE'
  CHECK (status IN ('ACTIVE', 'SUSPENDED')), media_quota_bytes INTEGER NOT NULL DEFAULT 20971520, avatar_media_hash TEXT
  REFERENCES media_assets(content_hash) ON DELETE SET NULL, experience INTEGER NOT NULL DEFAULT 0);
CREATE TABLE registration_invites (
  id TEXT PRIMARY KEY,
  code_hash TEXT NOT NULL UNIQUE,
  created_by TEXT,
  created_at TEXT NOT NULL,
  expires_at TEXT,
  used_at TEXT,
  used_by TEXT UNIQUE,
  FOREIGN KEY (created_by) REFERENCES users(id),
  FOREIGN KEY (used_by) REFERENCES users(id)
);
CREATE TABLE sessions (
  id_hash TEXT PRIMARY KEY,
  user_id TEXT NOT NULL,
  expires_at TEXT NOT NULL,
  created_at TEXT NOT NULL,
  last_seen_at TEXT,
  user_agent_hash TEXT NOT NULL,
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);
CREATE TABLE posts (
  id TEXT PRIMARY KEY,
  creator_id TEXT NOT NULL,
  title TEXT NOT NULL,
  author TEXT NOT NULL,
  content_html TEXT NOT NULL,
  content_text TEXT NOT NULL,
  tags_json TEXT NOT NULL DEFAULT '[]',
  license TEXT NOT NULL,
  revision_count INTEGER NOT NULL DEFAULT 1,
  change_note TEXT NOT NULL DEFAULT '',
  version INTEGER NOT NULL DEFAULT 1,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  deleted_at TEXT, public_id INTEGER, cover_media_hash TEXT
  REFERENCES media_assets(content_hash) ON DELETE SET NULL, classification_card_json TEXT NOT NULL DEFAULT '{}', citations_json TEXT NOT NULL DEFAULT '[]', visibility TEXT NOT NULL DEFAULT 'PUBLIC'
  CHECK (visibility IN ('PUBLIC', 'PRIVATE')), document_format TEXT NOT NULL DEFAULT 'html'
  CHECK (document_format IN ('html', 'ui-pdf')), ui_pdf_source TEXT NOT NULL DEFAULT '', ui_pdf_meta_json TEXT NOT NULL DEFAULT '{}', type TEXT NOT NULL DEFAULT '', content_laup TEXT, folder_id TEXT REFERENCES folders(id) ON DELETE SET NULL, content_kernel TEXT,
  FOREIGN KEY (creator_id) REFERENCES users(id)
);
CREATE TABLE post_revisions (
  post_id TEXT NOT NULL,
  revision_number INTEGER NOT NULL,
  title TEXT NOT NULL,
  content_html TEXT NOT NULL,
  change_note TEXT NOT NULL DEFAULT '',
  created_at TEXT NOT NULL,
  created_by TEXT NOT NULL, classification_card_json TEXT NOT NULL DEFAULT '{}', citations_json TEXT NOT NULL DEFAULT '[]', document_format TEXT NOT NULL DEFAULT 'html'
  CHECK (document_format IN ('html', 'ui-pdf')), ui_pdf_source TEXT NOT NULL DEFAULT '', content_laup TEXT, content_kernel TEXT,
  PRIMARY KEY (post_id, revision_number),
  FOREIGN KEY (post_id) REFERENCES posts(id) ON DELETE CASCADE,
  FOREIGN KEY (created_by) REFERENCES users(id)
);
CREATE TABLE sync_events (
  sequence INTEGER PRIMARY KEY AUTOINCREMENT,
  entity_type TEXT NOT NULL,
  entity_id TEXT NOT NULL,
  operation TEXT NOT NULL CHECK (operation IN ('UPSERT', 'DELETE')),
  version INTEGER NOT NULL,
  occurred_at TEXT NOT NULL
);
CREATE TABLE request_limits (
  key_hash TEXT PRIMARY KEY,
  window_started_at TEXT NOT NULL,
  attempts INTEGER NOT NULL,
  updated_at TEXT NOT NULL
);
CREATE TABLE user_devices (
  device_hash TEXT PRIMARY KEY,
  user_id TEXT NOT NULL,
  first_seen_at TEXT NOT NULL,
  last_seen_at TEXT NOT NULL,
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);
CREATE TABLE published_trees (
  id TEXT PRIMARY KEY,
  creator_id TEXT NOT NULL,
  kind TEXT NOT NULL CHECK (kind IN ('USER', 'OFFICIAL')),
  title TEXT NOT NULL,
  description TEXT NOT NULL DEFAULT '',
  document_json TEXT NOT NULL,
  node_count INTEGER NOT NULL,
  license TEXT NOT NULL,
  version INTEGER NOT NULL DEFAULT 1,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  deleted_at TEXT, public_id INTEGER, tags_json TEXT NOT NULL DEFAULT '[]', change_note TEXT NOT NULL DEFAULT '', fork_enabled INTEGER NOT NULL DEFAULT 0, contribution_enabled INTEGER NOT NULL DEFAULT 0, forked_from_tree_id TEXT
  REFERENCES published_trees(id), references_text TEXT NOT NULL DEFAULT '', image_credits_text TEXT NOT NULL DEFAULT '', platform_recommended INTEGER NOT NULL DEFAULT 0
  CHECK (platform_recommended IN (0, 1)), platform_reviewed_at TEXT, platform_reviewed_by TEXT
  REFERENCES users(id), visibility TEXT NOT NULL DEFAULT 'PUBLIC'
  CHECK (visibility IN ('PUBLIC', 'PRIVATE')),
  FOREIGN KEY (creator_id) REFERENCES users(id)
);
CREATE TABLE tree_revisions (
  tree_id TEXT NOT NULL,
  version INTEGER NOT NULL,
  title TEXT NOT NULL,
  description TEXT NOT NULL DEFAULT '',
  document_json TEXT NOT NULL,
  node_count INTEGER NOT NULL,
  license TEXT NOT NULL,
  created_at TEXT NOT NULL,
  created_by TEXT NOT NULL, tags_json TEXT NOT NULL DEFAULT '[]', change_note TEXT NOT NULL DEFAULT '', fork_enabled INTEGER NOT NULL DEFAULT 0, contribution_enabled INTEGER NOT NULL DEFAULT 0, references_text TEXT NOT NULL DEFAULT '', image_credits_text TEXT NOT NULL DEFAULT '',
  PRIMARY KEY (tree_id, version),
  FOREIGN KEY (tree_id) REFERENCES published_trees(id) ON DELETE CASCADE,
  FOREIGN KEY (created_by) REFERENCES users(id)
);
CREATE TABLE media_assets (
  content_hash TEXT PRIMARY KEY,
  object_key TEXT NOT NULL UNIQUE,
  mime_type TEXT NOT NULL CHECK (mime_type IN ('image/jpeg', 'image/png', 'image/webp')),
  byte_size INTEGER NOT NULL CHECK (byte_size > 0),
  width INTEGER NOT NULL CHECK (width > 0),
  height INTEGER NOT NULL CHECK (height > 0),
  created_by TEXT NOT NULL,
  created_at TEXT NOT NULL,
  FOREIGN KEY (created_by) REFERENCES users(id)
);
CREATE TABLE media_owners (
  content_hash TEXT NOT NULL,
  user_id TEXT NOT NULL,
  created_at TEXT NOT NULL,
  PRIMARY KEY (content_hash, user_id),
  FOREIGN KEY (content_hash) REFERENCES media_assets(content_hash) ON DELETE CASCADE,
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);
CREATE TABLE media_user_usage (
  user_id TEXT PRIMARY KEY,
  used_bytes INTEGER NOT NULL DEFAULT 0 CHECK (used_bytes >= 0),
  updated_at TEXT NOT NULL,
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);
CREATE TABLE media_global_usage (
  id INTEGER PRIMARY KEY CHECK (id = 1),
  used_bytes INTEGER NOT NULL DEFAULT 0 CHECK (used_bytes >= 0),
  updated_at TEXT NOT NULL
);
CREATE TABLE media_references (
  content_hash TEXT NOT NULL,
  entity_type TEXT NOT NULL CHECK (entity_type IN ('POST', 'TREE')),
  entity_id TEXT NOT NULL,
  created_at TEXT NOT NULL,
  PRIMARY KEY (content_hash, entity_type, entity_id),
  FOREIGN KEY (content_hash) REFERENCES media_assets(content_hash) ON DELETE CASCADE
);
CREATE TABLE registration_invite_links (
  id TEXT PRIMARY KEY,
  token_hash TEXT NOT NULL UNIQUE,
  label TEXT NOT NULL,
  created_by TEXT NOT NULL,
  created_at TEXT NOT NULL,
  expires_at TEXT NOT NULL,
  max_uses INTEGER NOT NULL CHECK (max_uses BETWEEN 2 AND 5000),
  use_count INTEGER NOT NULL DEFAULT 0 CHECK (use_count >= 0 AND use_count <= max_uses),
  last_used_at TEXT,
  revoked_at TEXT,
  FOREIGN KEY (created_by) REFERENCES users(id)
);
CREATE TABLE registration_invite_link_uses (
  link_id TEXT NOT NULL,
  user_id TEXT NOT NULL UNIQUE,
  used_at TEXT NOT NULL,
  PRIMARY KEY (link_id, user_id),
  FOREIGN KEY (link_id) REFERENCES registration_invite_links(id) ON DELETE CASCADE,
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);
CREATE TABLE user_follows (
  follower_id TEXT NOT NULL,
  followed_id TEXT NOT NULL,
  created_at TEXT NOT NULL,
  PRIMARY KEY (follower_id, followed_id),
  CHECK (follower_id <> followed_id),
  FOREIGN KEY (follower_id) REFERENCES users(id) ON DELETE CASCADE,
  FOREIGN KEY (followed_id) REFERENCES users(id) ON DELETE CASCADE
);
CREATE TABLE content_comments (
  id TEXT PRIMARY KEY,
  target_type TEXT NOT NULL CHECK (target_type IN ('POST', 'TREE')),
  target_id TEXT NOT NULL,
  creator_id TEXT NOT NULL,
  content TEXT NOT NULL,
  created_at TEXT NOT NULL,
  deleted_at TEXT, root_id TEXT, reply_to_id TEXT,
  FOREIGN KEY (creator_id) REFERENCES users(id) ON DELETE CASCADE
);
CREATE TABLE content_likes (
  target_type TEXT NOT NULL CHECK (target_type IN ('POST', 'TREE')),
  target_id TEXT NOT NULL,
  user_id TEXT NOT NULL,
  created_at TEXT NOT NULL,
  PRIMARY KEY (target_type, target_id, user_id),
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);
CREATE TABLE content_favorites (
  target_type TEXT NOT NULL CHECK (target_type IN ('POST', 'TREE')),
  target_id TEXT NOT NULL,
  user_id TEXT NOT NULL,
  created_at TEXT NOT NULL,
  PRIMARY KEY (target_type, target_id, user_id),
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);
CREATE TABLE content_stats (
  target_type TEXT NOT NULL CHECK (target_type IN ('POST', 'TREE')),
  target_id TEXT NOT NULL,
  view_count INTEGER NOT NULL DEFAULT 0 CHECK (view_count >= 0),
  updated_at TEXT NOT NULL,
  PRIMARY KEY (target_type, target_id)
);
CREATE TABLE experience_events (
  user_id TEXT NOT NULL,
  dedupe_key TEXT NOT NULL,
  event_type TEXT NOT NULL CHECK (event_type IN ('DAILY_LOGIN', 'POST_CREATED', 'TREE_CREATED')),
  points INTEGER NOT NULL CHECK (points > 0 AND points <= 1000),
  occurred_at TEXT NOT NULL,
  PRIMARY KEY (user_id, dedupe_key),
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);
CREATE TABLE tree_forks (
  id TEXT PRIMARY KEY,
  source_tree_id TEXT NOT NULL,
  user_id TEXT NOT NULL,
  source_version INTEGER NOT NULL,
  published_tree_id TEXT,
  created_at TEXT NOT NULL,
  UNIQUE (source_tree_id, user_id),
  FOREIGN KEY (source_tree_id) REFERENCES published_trees(id),
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
  FOREIGN KEY (published_tree_id) REFERENCES published_trees(id)
);
CREATE TABLE tree_contributions (
  id TEXT PRIMARY KEY,
  target_tree_id TEXT NOT NULL,
  contributor_id TEXT NOT NULL,
  base_version INTEGER NOT NULL,
  title TEXT NOT NULL,
  description TEXT NOT NULL DEFAULT '',
  document_json TEXT NOT NULL,
  node_count INTEGER NOT NULL,
  license TEXT NOT NULL,
  tags_json TEXT NOT NULL DEFAULT '[]',
  change_note TEXT NOT NULL,
  fork_enabled INTEGER NOT NULL DEFAULT 0,
  contribution_enabled INTEGER NOT NULL DEFAULT 0,
  status TEXT NOT NULL DEFAULT 'PENDING'
    CHECK (status IN ('PENDING', 'APPROVED', 'REJECTED')),
  review_note TEXT NOT NULL DEFAULT '',
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  reviewed_at TEXT,
  reviewed_by TEXT, references_text TEXT NOT NULL DEFAULT '', image_credits_text TEXT NOT NULL DEFAULT '',
  FOREIGN KEY (target_tree_id) REFERENCES published_trees(id),
  FOREIGN KEY (contributor_id) REFERENCES users(id) ON DELETE CASCADE,
  FOREIGN KEY (reviewed_by) REFERENCES users(id)
);
CREATE TABLE tree_official_requests (
  id TEXT PRIMARY KEY,
  tree_id TEXT NOT NULL,
  applicant_id TEXT NOT NULL,
  author_id TEXT NOT NULL,
  message TEXT NOT NULL DEFAULT '',
  status TEXT NOT NULL DEFAULT 'PENDING'
    CHECK (status IN ('PENDING', 'APPROVED', 'REJECTED', 'WITHDRAWN')),
  response_note TEXT NOT NULL DEFAULT '',
  official_tree_id TEXT,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  responded_at TEXT,
  FOREIGN KEY (tree_id) REFERENCES published_trees(id),
  FOREIGN KEY (applicant_id) REFERENCES users(id) ON DELETE CASCADE,
  FOREIGN KEY (author_id) REFERENCES users(id) ON DELETE CASCADE,
  FOREIGN KEY (official_tree_id) REFERENCES published_trees(id)
);
CREATE TABLE notifications (
  id TEXT PRIMARY KEY,
  recipient_id TEXT NOT NULL,
  actor_id TEXT,
  type TEXT NOT NULL CHECK (type IN (
    'COMMENT_POST',
    'COMMENT_TREE',
    'CONTRIBUTION_SUBMITTED',
    'CONTRIBUTION_APPROVED',
    'CONTRIBUTION_REJECTED',
    'OFFICIAL_TREE_REQUESTED',
    'OFFICIAL_TREE_APPROVED',
    'OFFICIAL_TREE_REJECTED'
  )),
  target_type TEXT NOT NULL CHECK (target_type IN ('POST', 'TREE', 'CONTRIBUTION')),
  target_id TEXT NOT NULL,
  source_id TEXT NOT NULL,
  message TEXT NOT NULL DEFAULT '',
  read_at TEXT,
  created_at TEXT NOT NULL,
  UNIQUE (recipient_id, type, source_id),
  FOREIGN KEY (recipient_id) REFERENCES users(id) ON DELETE CASCADE,
  FOREIGN KEY (actor_id) REFERENCES users(id) ON DELETE SET NULL
);
CREATE TABLE private_work_slots (
  owner_id TEXT NOT NULL,
  slot_number INTEGER NOT NULL CHECK (slot_number BETWEEN 1 AND 5),
  entity_type TEXT NOT NULL CHECK (entity_type IN ('POST', 'TREE')),
  entity_id TEXT NOT NULL,
  created_at TEXT NOT NULL,
  PRIMARY KEY (owner_id, slot_number),
  UNIQUE (entity_type, entity_id),
  FOREIGN KEY (owner_id) REFERENCES users(id) ON DELETE CASCADE
);
CREATE TABLE home_gallery_images (
  slot_number INTEGER PRIMARY KEY CHECK (slot_number BETWEEN 1 AND 10),
  content_hash TEXT NOT NULL UNIQUE,
  selected_by TEXT NOT NULL,
  selected_at TEXT NOT NULL,
  FOREIGN KEY (content_hash) REFERENCES media_assets(content_hash) ON DELETE CASCADE,
  FOREIGN KEY (selected_by) REFERENCES users(id) ON DELETE CASCADE
);
CREATE TABLE post_drafts (
  id TEXT PRIMARY KEY,
  creator_id TEXT NOT NULL,
  content_type TEXT NOT NULL DEFAULT 'ARTICLE'
    CHECK (content_type IN ('ARTICLE', 'TREE')),
  document_format TEXT NOT NULL DEFAULT 'html'
    CHECK (document_format IN ('html', 'ui-pdf')),
  mode TEXT NOT NULL DEFAULT 'CREATE'
    CHECK (mode IN ('CREATE', 'EDIT', 'FORK', 'CONTRIBUTION')),
  target_id TEXT NOT NULL DEFAULT '',
  base_version INTEGER NOT NULL DEFAULT 0,
  title TEXT NOT NULL DEFAULT '',
  content_html TEXT NOT NULL DEFAULT '',
  ui_pdf_source TEXT NOT NULL DEFAULT '',
  ui_pdf_meta_json TEXT NOT NULL DEFAULT '{}',
  classification_card_json TEXT NOT NULL DEFAULT '{}',
  citations_json TEXT NOT NULL DEFAULT '[]',
  tags_json TEXT NOT NULL DEFAULT '[]',
  cover_media_hash TEXT,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  FOREIGN KEY (creator_id) REFERENCES users(id) ON DELETE CASCADE
);
CREATE TABLE mobile_auth_handoffs (
  code_hash TEXT PRIMARY KEY,
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  expires_at TEXT NOT NULL,
  created_at TEXT NOT NULL,
  used_at TEXT
);
CREATE TABLE collections (
  id TEXT PRIMARY KEY,
  owner_id TEXT NOT NULL,
  title TEXT NOT NULL,
  description TEXT NOT NULL DEFAULT '',
  visibility TEXT NOT NULL DEFAULT 'PUBLIC'
    CHECK (visibility IN ('PUBLIC', 'PRIVATE')),
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  deleted_at TEXT,
  FOREIGN KEY (owner_id) REFERENCES users(id) ON DELETE CASCADE
);
CREATE TABLE collection_items (
  collection_id TEXT NOT NULL,
  target_type TEXT NOT NULL CHECK (target_type IN ('POST', 'TREE')),
  target_id TEXT NOT NULL,
  sort_order INTEGER NOT NULL DEFAULT 0,
  added_at TEXT NOT NULL,
  PRIMARY KEY (collection_id, target_type, target_id),
  FOREIGN KEY (collection_id) REFERENCES collections(id) ON DELETE CASCADE
);
CREATE TABLE folders (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  section TEXT NOT NULL DEFAULT 'none'
    CHECK (section IN ('science', 'news', 'none')),
  creator_id TEXT NOT NULL,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL, is_private INTEGER NOT NULL DEFAULT 0,
  FOREIGN KEY (creator_id) REFERENCES users(id) ON DELETE CASCADE
);
CREATE TABLE ls_projects (
  uid TEXT PRIMARY KEY, title TEXT NOT NULL, owner_id TEXT NOT NULL REFERENCES users(id),
  revision TEXT NOT NULL, object_key TEXT NOT NULL, updated_at TEXT NOT NULL
);
CREATE TABLE ls_main (
  singleton INTEGER PRIMARY KEY CHECK(singleton=1), project_uid TEXT NOT NULL REFERENCES ls_projects(uid)
);
CREATE TABLE ls_edit_leases (
  token TEXT PRIMARY KEY, project_uid TEXT NOT NULL REFERENCES ls_projects(uid), root_uid TEXT NOT NULL,
  owner_id TEXT NOT NULL REFERENCES users(id), revision TEXT NOT NULL, scope_json TEXT NOT NULL,
  expires_at INTEGER NOT NULL
);
CREATE TABLE ls_revision_log (
  revision TEXT PRIMARY KEY, project_uid TEXT NOT NULL, parent_revision TEXT, author_id TEXT NOT NULL,
  root_uid TEXT, object_key TEXT NOT NULL, created_at TEXT NOT NULL
);
DELETE FROM sqlite_sequence;
CREATE INDEX idx_sessions_user ON sessions(user_id);
CREATE INDEX idx_sessions_expiry ON sessions(expires_at);
CREATE INDEX idx_posts_updated ON posts(deleted_at, updated_at DESC, id DESC);
CREATE INDEX idx_posts_creator ON posts(creator_id, updated_at DESC);
CREATE INDEX idx_sync_sequence ON sync_events(sequence);
CREATE INDEX idx_user_devices_user ON user_devices(user_id);
CREATE INDEX idx_published_trees_kind_updated
  ON published_trees(kind, deleted_at, updated_at DESC, id DESC);
CREATE INDEX idx_published_trees_creator
  ON published_trees(creator_id, deleted_at, updated_at DESC);
CREATE UNIQUE INDEX idx_users_public_id ON users(public_id);
CREATE UNIQUE INDEX idx_posts_public_id ON posts(public_id);
CREATE UNIQUE INDEX idx_published_trees_public_id ON published_trees(public_id);
CREATE INDEX idx_users_status_public_id ON users(status, public_id DESC);
CREATE INDEX idx_media_owners_user ON media_owners(user_id, created_at DESC);
CREATE INDEX idx_media_references_entity
  ON media_references(entity_type, entity_id);
CREATE INDEX idx_media_references_hash
  ON media_references(content_hash);
CREATE INDEX idx_registration_invite_links_created
  ON registration_invite_links(created_at DESC);
CREATE INDEX idx_registration_invite_links_active
  ON registration_invite_links(token_hash, revoked_at, expires_at);
CREATE INDEX idx_registration_invite_link_uses_link
  ON registration_invite_link_uses(link_id, used_at DESC);
CREATE INDEX idx_user_follows_followed
  ON user_follows(followed_id, created_at DESC);
CREATE INDEX idx_content_comments_target
  ON content_comments(target_type, target_id, deleted_at, created_at DESC);
CREATE INDEX idx_content_comments_creator
  ON content_comments(creator_id, created_at DESC);
CREATE INDEX idx_content_likes_target
  ON content_likes(target_type, target_id, created_at DESC);
CREATE INDEX idx_content_favorites_target
  ON content_favorites(target_type, target_id, created_at DESC);
CREATE INDEX idx_content_favorites_user
  ON content_favorites(user_id, created_at DESC);
CREATE INDEX idx_experience_events_user
  ON experience_events(user_id, occurred_at DESC);
CREATE INDEX idx_posts_cover_media_hash
  ON posts(cover_media_hash);
CREATE INDEX idx_tree_forks_source
  ON tree_forks(source_tree_id, created_at DESC);
CREATE INDEX idx_tree_forks_user
  ON tree_forks(user_id, created_at DESC);
CREATE INDEX idx_tree_contributions_target
  ON tree_contributions(target_tree_id, status, updated_at DESC);
CREATE INDEX idx_tree_contributions_contributor
  ON tree_contributions(contributor_id, updated_at DESC);
CREATE INDEX idx_content_comments_roots
  ON content_comments(
    target_type,
    target_id,
    root_id,
    deleted_at,
    created_at DESC,
    id DESC
  );
CREATE INDEX idx_content_comments_replies
  ON content_comments(root_id, deleted_at, created_at ASC, id ASC);
CREATE INDEX idx_content_comments_reply_to
  ON content_comments(reply_to_id, deleted_at);
CREATE INDEX idx_tree_official_requests_tree
  ON tree_official_requests(tree_id, status, updated_at DESC);
CREATE INDEX idx_tree_official_requests_author
  ON tree_official_requests(author_id, status, updated_at DESC);
CREATE INDEX idx_tree_official_requests_applicant
  ON tree_official_requests(applicant_id, status, updated_at DESC);
CREATE UNIQUE INDEX idx_tree_official_requests_pending
  ON tree_official_requests(tree_id) WHERE status = 'PENDING';
CREATE INDEX idx_notifications_recipient
  ON notifications(recipient_id, read_at, created_at DESC);
CREATE INDEX idx_published_trees_platform_recommended
  ON published_trees(platform_recommended, deleted_at, updated_at DESC, id DESC);
CREATE INDEX idx_posts_private_owner
  ON posts(creator_id, visibility, deleted_at, updated_at DESC);
CREATE INDEX idx_published_trees_private_owner
  ON published_trees(creator_id, visibility, deleted_at, updated_at DESC);
CREATE INDEX idx_private_work_slots_entity
  ON private_work_slots(entity_type, entity_id);
CREATE INDEX idx_home_gallery_selected
  ON home_gallery_images(selected_at DESC);
CREATE INDEX idx_post_drafts_creator
  ON post_drafts(creator_id, updated_at DESC);
CREATE INDEX idx_post_drafts_target
  ON post_drafts(target_id, mode);
CREATE INDEX idx_mobile_auth_handoffs_expiry
  ON mobile_auth_handoffs(expires_at);
CREATE INDEX idx_collections_owner
  ON collections(owner_id, deleted_at, updated_at DESC);
CREATE INDEX idx_collections_public
  ON collections(visibility, deleted_at, updated_at DESC);
CREATE INDEX idx_collection_items_order
  ON collection_items(collection_id, sort_order, added_at);
CREATE INDEX idx_collection_items_target
  ON collection_items(target_type, target_id);
CREATE INDEX idx_folders_section
  ON folders(section, created_at ASC);
CREATE INDEX idx_posts_folder
  ON posts(folder_id, deleted_at, updated_at DESC);
CREATE INDEX ls_leases_project_expiry ON ls_edit_leases(project_uid, expires_at);
CREATE TRIGGER users_assign_public_id
AFTER INSERT ON users
WHEN NEW.public_id IS NULL
BEGIN
  UPDATE users
     SET public_id = (SELECT COALESCE(MAX(public_id), 0) + 1 FROM users WHERE id <> NEW.id)
   WHERE id = NEW.id;
END;
CREATE TRIGGER posts_assign_public_id
AFTER INSERT ON posts
WHEN NEW.public_id IS NULL
BEGIN
  UPDATE posts
     SET public_id = (SELECT COALESCE(MAX(public_id), 0) + 1 FROM posts WHERE id <> NEW.id)
   WHERE id = NEW.id;
END;
CREATE TRIGGER published_trees_assign_public_id
AFTER INSERT ON published_trees
WHEN NEW.public_id IS NULL
BEGIN
  UPDATE published_trees
     SET public_id = (
       SELECT COALESCE(MAX(public_id), 0) + 1
         FROM published_trees
        WHERE id <> NEW.id
     )
   WHERE id = NEW.id;
END;
CREATE TRIGGER users_create_media_usage
AFTER INSERT ON users
BEGIN
  INSERT OR IGNORE INTO media_user_usage (user_id, used_bytes, updated_at)
  VALUES (NEW.id, 0, NEW.created_at);
END;
CREATE TRIGGER media_assets_increase_global_usage
AFTER INSERT ON media_assets
BEGIN
  UPDATE media_global_usage
     SET used_bytes = used_bytes + NEW.byte_size,
         updated_at = NEW.created_at
   WHERE id = 1;
END;
CREATE TRIGGER media_assets_decrease_global_usage
AFTER DELETE ON media_assets
BEGIN
  UPDATE media_global_usage
     SET used_bytes = MAX(0, used_bytes - OLD.byte_size),
         updated_at = CURRENT_TIMESTAMP
   WHERE id = 1;
END;
CREATE TRIGGER media_owners_increase_user_usage
AFTER INSERT ON media_owners
BEGIN
  INSERT OR IGNORE INTO media_user_usage (user_id, used_bytes, updated_at)
  VALUES (NEW.user_id, 0, NEW.created_at);
  UPDATE media_user_usage
     SET used_bytes = used_bytes + (
           SELECT byte_size FROM media_assets WHERE content_hash = NEW.content_hash
         ),
         updated_at = NEW.created_at
   WHERE user_id = NEW.user_id;
END;
CREATE TRIGGER media_owners_decrease_user_usage
AFTER DELETE ON media_owners
BEGIN
  UPDATE media_user_usage
     SET used_bytes = MAX(0, used_bytes - COALESCE(
           (SELECT byte_size FROM media_assets WHERE content_hash = OLD.content_hash), 0
         )),
         updated_at = CURRENT_TIMESTAMP
   WHERE user_id = OLD.user_id;
END;
CREATE TRIGGER experience_events_award
AFTER INSERT ON experience_events
BEGIN
  UPDATE users
     SET experience = experience + NEW.points,
         level = CAST((experience + NEW.points) / 100 AS INTEGER)
   WHERE id = NEW.user_id;
END;
CREATE TRIGGER users_protect_site_owner_role
BEFORE UPDATE OF role, status ON users
WHEN OLD.public_id = 1
 AND (NEW.role <> 'ADMIN' OR NEW.status <> 'ACTIVE')
BEGIN
  SELECT RAISE(ABORT, 'SITE_OWNER_MUST_REMAIN_ACTIVE_ADMIN');
END;
