INSERT INTO "post_revisions" ("post_id","revision_number","title","content_html","change_note","created_at","created_by","classification_card_json","citations_json","document_format","ui_pdf_source","content_laup","content_kernel") VALUES('fe920fdb-c7b2-4309-ad26-fc49b064b5a5',2,'小风整理：CANN算子挑战赛(江山赛区)赛题和评分规则解读',replace('<h1>CANN算子挑战赛(江山赛区)赛题和评分规则解读</h1><p> b站连接：<a href="https://www.bilibili.com/video/BV1r3546UE5h/?spm_id_from=333.1391.0.0&amp;vd_source=ff261b58a096735e2852b0bfa9161606" target="_blank" rel="noopener noreferrer nofollow">https://www.bilibili.com/video/BV1r3546UE5h/spm_id_from=333.1391.0.0&amp;vd_source=ff261b58a096735e2852b0bfa9161606</a> </p><p><br></p><figure><img src="/media/d12942c3dc6ab436dfcd181708607802c1bad00eabfb95e7ba73026c8065e328" alt="image" loading="lazy" referrerpolicy="no-referrer"><figcaption>image</figcaption></figure><p><br></p><figure><img src="/media/18910314673aacab96509853550184e35b7b627048f2daf01a52507cfb48d225" alt="image" loading="lazy" referrerpolicy="no-referrer"><figcaption>image</figcaption></figure><p><br></p><figure><img src="/media/f8dbd06c1c12ba5863a35f2be1a6268d91145b1b808e537364d335c88bda9b4f" alt="image" loading="lazy" referrerpolicy="no-referrer"><figcaption>image</figcaption></figure><p><br></p><figure><img src="/media/28274fb0bc0e9f43fdee88325fa3622dcfe2302a1cd2ed3dbe32d8fde12d9569" alt="image" loading="lazy" referrerpolicy="no-referrer"><figcaption>image</figcaption></figure><pre><code>#include &lt;cmath&gt;\n#include &lt;cstdint&gt;\n#include &lt;iostream&gt;\n#include &lt;vector&gt;\n\n// ------------------------------------------------------------\n// 正式 AICore 版：这是最接近真实 Ascend kernel 的代码结构。\n// 需要真实的 Ascend Toolkit / kernel_operator.h / ccec 编译器。\n// 这不是纯主机 C++ 可直接运行版本。\n//\n// 对新手来说，可以把它理解为：\n// 1) 先从全局显存读数据\n// 2) 把数据切成一个个 tile\n// 3) 在片上计算\n// 4) 把结果写回全局显存\n// 这就是 Ascend kernel 的典型流水线思路。\n// ------------------------------------------------------------\n\n// 头文件：Ascend C 的基础库，里面定义了 GM_ADDR、TPipe、TQue、LocalTensor 等类型。\n#include "kernel_operator.h"\nusing namespace AscendC;\n\n\n\n\n        //使用多核计算-&gt;数据切片-&gt;获取每个核实际需要处理的在Global Memory上的地址偏移量\n        //BlockDim（多核间切分）：\n        //TileNum（单核内切分）：\n\n    int32_t totalLength=8*1024;\n\n    int32_t USE_CORE_NUM=8;\n    int32_t BLOCK_LENGTH=totalLength/USE_CORE_NUM;\n\n    int32_t TILE_NUM=8;\n    // 队列深度为 1，表示只开一个缓冲区来做输入/输出流转。\n    constexpr int32_t BUFFER_NUM = 2;\n\n    int32_t TILE_LENGTH=BLOCK_LENGTH/ TILE_NUM / BUFFER_NUM;\n\n\n// ------------------------------------------------------------\n// erf 近似计算函数：这里的数学公式和前面的 C++ 版本一致。\n// 但这个版本更偏“硬件 kernel 写法”，更适合放到 AICore 中计算。\n// ------------------------------------------------------------\nstatic __aicore__ inline float erfApproxAicore(float x) {\n    // 1) 先取绝对值，方便处理正负号。\n    const float ax = std::abs(x);\n\n    // 2) 对大输入做饱和处理：|x| &gt; 3.92 时，erf(x) 接近 ±1。\n    // 这样能避免大数值导致公式失真，也减少计算量。\n    if (ax &gt; 3.92f) {\n        return x &gt; 0.0f ? 1.0f : -1.0f;\n    }\n\n    // 3) 近似参数：这是 erf 经典近似公式的系数。\n    const float p = 0.3275911f;\n    const float a1 = 0.254829592f;\n    const float a2 = -0.284496736f;\n    const float a3 = 1.421413741f;\n    const float a4 = -1.453152027f;\n    const float a5 = 1.061405429f;\n\n    // 4) 计算 t，这一步是为了把复杂的 erf 近似压成一个低阶多项式。\n    const float t = 1.0f / (1.0f + p * ax);\n\n    // 5) 构造多项式近似：\n    //    poly = (((((a5*t + a4)*t + a3)*t + a2)*t + a1)*t)\n    const float poly = (((((a5 * t + a4) * t + a3) * t + a2) * t + a1) * t);\n\n    // 6) 根据 erf 的性质，对负数取反号。\n    const float value = 1.0f - poly * std::exp(-ax * ax);\n    return x &gt;= 0.0f ? value : -value;\n}\n\n// ------------------------------------------------------------\n// KernelErfAicore：这是一个 AICore kernel 的类封装。\n// 它把 kernel 的三大步骤拆成了三个函数：\n// 1) CopyIn：数据搬运进来\n// 2) Compute：在芯片上做计算\n// 3) CopyOut：结果搬回去\n// ------------------------------------------------------------\nclass KernelErfAicore {\npublic:\n    // 构造函数：没有做复杂事，保持接口简单。\n    __aicore__ inline KernelErfAicore() {}\n\n    // --------------------------------------------------------\n    // Init：初始化内核需要的状态。\n    // 输入：\n    //   x = 输入数据的全局地址\n    //   y = 输出数据的全局地址\n    //   totalLength = 输入长度\n    // --------------------------------------------------------\n    __aicore__ inline void Init(GM_ADDR x, GM_ADDR y, uint32_t totalLength) {\n        //this-&gt;totalLength = totalLength;\n        //this-&gt;tileNum = totalLength / TILE_LEN;\n\n\n\n        // 把全局显存地址绑定到两个 GlobalTensor 上。\n        // 也就是把“内存地址”映射到 kernel 中可操作的 tensor。\n        //BlockIdx() 物理地址\n        xGm.SetGlobalBuffer((__gm__ float*)x+GetBlockIdx()*BLOCK_LENGTH，BLOCK_LENGTH);\n        yGm.SetGlobalBuffer((__gm__ float*)y+GetBlockIdx()*BLOCK_LENGTH，BLOCK_LENGTH);\n\n        // 创建输入队列和输出队列，大小根据 TILE_LENGTH 分配。\n        //  // 让管家为传送带分配片上内存空间\n        pipe.InitBuffer(inQueueX, BUFFER_NUM, TILE_LENGTH * sizeof(float));\n        pipe.InitBuffer(outQueueY, BUFFER_NUM, TILE_LENGTH * sizeof(float));\n    }\n\n    // --------------------------------------------------------\n    // Process：主调度循环。\n    // 整个数组会被拆成多个 tile，逐个处理。\n    // --------------------------------------------------------\n    __aicore__ inline void Process() {\n        for (uint32_t i = 0; i &lt; tileNum* BUFFER_NUM; ++i) {\n            CopyIn(i);   // 1. 读入一个 tile\n            Compute(i);   // 2. 在片上计算\n            CopyOut(i);  // 3. 写回一个 tile\n        }\n    }\n\nprivate:\n    // --------------------------------------------------------\n    // CopyIn：从全局显存中读取一个 256 元素的 tile。\n    // 这里先申请一个 LocalTensor，用于存放输入数据的片上缓存。\n    // --------------------------------------------------------\n    __aicore__ inline void CopyIn(uint32_t progress) {\n        // 申请一块本地片上缓存，大小就是一个 tile。\n        LocalTensor&lt;float&gt; xLocal = inQueueX.AllocTensor&lt;float&gt;();\n\n        // 把 GM 中当前偏移位置的 256 个元素复制到 xLocal。\n        DataCopy(xLocal, xGm[progress * TILE_LENGTH], TILE_LENGTH);\n\n        // 把 xLocal 放到输入队列里，供后续计算阶段使用。\n        inQueueX.EnQue(xLocal);\n    }\n\n    // --------------------------------------------------------\n    // Compute：真正执行 erf 近似计算。\n    // 先从输入队列拿出一个 tile，然后逐元素计算，最后放到输出队列。\n    // --------------------------------------------------------\n    __aicore__ inline void Compute() {\n        // 取出输入 tile\n        LocalTensor&lt;float&gt; xLocal = inQueueX.DeQue&lt;float&gt;();\n\n        // 申请输出 tile 缓冲区\n        LocalTensor&lt;float&gt; yLocal = outQueueY.AllocTensor&lt;float&gt;();\n\n        // 逐元素计算 erf 近似值\n        for (int32_t idx = 0; idx &lt; TILE_LENGTH; ++idx) {\n            yLocal[idx] = erfApproxAicore(xLocal[idx]);\n        }\n\n        // 计算完成后，释放输入缓存，并把输出放到输出队列。\n        inQueueX.FreeTensor(xLocal);\n        outQueueY.EnQue(yLocal);\n    }\n\n    // --------------------------------------------------------\n    // CopyOut：把计算结果写回全局显存。\n    // --------------------------------------------------------\n    __aicore__ inline void CopyOut(uint32_t progress) {\n        // 从输出队列取出结果 tile\n        LocalTensor&lt;float&gt; yLocal = outQueueY.DeQue&lt;float&gt;();\n\n        // 写回到全局显存的对应位置\n        DataCopy(yGm[progress * TILE_LENGTH], yLocal, TILE_LENGTH);\n\n        // 释放输出缓存\n        outQueueY.FreeTensor(yLocal);\n    }\n\nprivate:\n    // 下面是 AICore 常见的对象：\n    // - TPipe：管理片上 buffer/队列资源\n    // - TQue：输入输出队列\n    // - GlobalTensor：对全局显存地址的包装\n    TPipe pipe;\n    TQue&lt;QuePosition::VECIN, BUFFER_NUM&gt; inQueueX;\n    TQue&lt;QuePosition::VECOUT, BUFFER_NUM&gt; outQueueY;\n    //INPUT OUTPUT\n    GlobalTensor&lt;float&gt; xGm;\n    GlobalTensor&lt;float&gt; yGm;\n\n    uint32_t totalLength;\n    uint32_t tileNum;\n};\n\n// ------------------------------------------------------------\n// kernel 入口函数：\n// 这是真正给 Ascend 编译器看的核函数入口，名字和参数形式都很像 C 语言接口。\n// 创建对象op。调用Init(),pocess();\n// ----.--------------------------------------------------------\nextern "C" __global__ __aicore__ void erf_aicore_kernel(GM_ADDR x, GM_ADDR y, uint32_t totalLength) {\n    KernelErfAicore op;\n    op.Init(x, y, totalLength);\n    op.Process();\n}\n\n// ------------------------------------------------------------\n// Host 侧启动函数：\n// 这部分通常是 host 端包装，调用核函数。\n// 这里的写法和 CUDA 的 kernel launch 非常类似。\n//&lt;&lt;&lt;   &gt;&gt;&gt;\n// ------------------------------------------------------------\n#ifndef __CCE_KT_TEST__\nvoid erf_aicore_kernel_do(uint32_t blockDim, void* stream, uint8_t* x, uint8_t* y, uint32_t totalLength) {\n    erf_aicore_kernel&lt;&lt;&lt;blockDim, nullptr, stream&gt;&gt;&gt;(x, y, totalLength);\n}\n#endif\n\n\n\n\n// ------------------------------------------------------------\n// main：\n// 这个文件本质上不是为了本机直接跑写的，\n// 主要是为了展示正式 AICore 的结构和代码组织方式。\n// ------------------------------------------------------------\nint main() {\n    std::cout &lt;&lt; "[AICORE] 这是正式 Ascend kernel 的结构示例，不能直接用普通 g++ 运行。" &lt;&lt; std::endl;\n    return 0;\n}\n</code></pre><p><br></p>','\n',char(10)),'2026年9月7日 14:37 第1次提交','2026-09-07T07:53:29.782Z','69ce3b6d-41f1-42f7-b766-cf9784bdeb0d','{"cards":[]}','[]','html','',NULL,NULL);
INSERT INTO "post_revisions" ("post_id","revision_number","title","content_html","change_note","created_at","created_by","classification_card_json","citations_json","document_format","ui_pdf_source","content_laup","content_kernel") VALUES('e1422a4e-751b-4713-bc52-d1d27d074369',1,'真核生物的分类与系统发育','<p>本条目对真核生物内部的分类与系统发育学研究进行了整理，尤其关注近年最新的成果；前面大部分篇幅是在描述历史，若只想看观点和最新的成果，请直接翻到后三个章节；关于真核生物的起源，请参阅阿斯加德古菌相关章节。由于具有时效性，所以请编辑者务必附上最后更新的日期：2026/09/07。</p><h1>引入：早期和近代研究</h1><p>在古代，人们就已认识到<strong>动物</strong>和<strong>植物</strong>应分为两类；这两个类群在林奈（<span style="color: rgb(32, 33, 34); background-color: rgb(255, 255, 255); font-size: 16px">C. Linnaeus</span>）时期被赋予了“<strong>界</strong>”的等级，意味着<strong>两界系统</strong>的形成（林奈还主张所谓“矿物界”，但后续很快被废止）<a href="#post-citation-1"><sup>[1]</sup></a>​；在这段时期，<strong>真菌</strong>被认为是一种植物。在显微镜被发明之后，人们也自然地将微生物根据是否可以进行光合作用划分为<strong>藻类</strong>和<strong>原生动物</strong>，并分别划归<strong>植物界</strong>（Plantae）和<strong>动物界</strong>（Animalia）<a href="#post-citation-2"><sup>[2]</sup></a>​。1866年，海克尔（E. Haeckel）将藻类和原生动物一起划入了<strong>原生生物界</strong>（<span style="color: rgb(32, 33, 34); background-color: rgb(255, 255, 255); font-size: 16px">Protista</span>），与动物和植物区分<a href="#post-citation-2"><sup>[2]</sup></a>​；他同时还意识到了真菌的特殊性，并将其从植物界迁移至原生生物界<a href="#post-citation-2"><sup>[2]</sup></a>​。自此，<strong>三界系统</strong>替代了两界系统成为主流。</p><p>随着显微技术的发展，人们逐渐意识到了<strong>细胞核</strong>在生物分类方面的重要性。1925年，爱德华·查顿（<span style="color: rgb(32, 33, 34); background-color: rgb(255, 255, 255); font-size: 16px">É. Chatton</span>）首次明确区分了<strong>原核生物</strong>（prokaryotes）与<strong>真核生物</strong>（eukaryotes）<a href="#post-citation-3"><sup>[3]</sup></a>​，分别用以指代那些“具有不明确细胞核的”和“具有明确细胞核的”生物。随后，赫伯特·科普兰（H. Copeland）等人将<strong>原核界</strong>（Monera）纳入分类体系<a href="#post-citation-4"><sup>[4]</sup></a>​，标志着<strong>四界系统</strong>的形成。1969年，罗伯特·惠特克（R. Whittaker）提出，真菌应当被视为一个单独的界（即<strong>真菌界</strong>（Fungi）），而不是被包含在植物界或者原生生物界中<a href="#post-citation-2"><sup>[2]</sup></a>​<a href="#post-citation-5"><sup>[5]</sup></a>​。据此，他提出了被广泛认可的<strong>五界系统</strong>，其影响力之大以至于直到现在，许多非高等教育的教材仍在采用五界系统。</p><p>1966年，琳恩·玛古莉斯（<span style="color: rgb(32, 33, 34); background-color: rgb(255, 255, 255); font-size: 16px">L. Margulis</span>）提出了<strong>内共生理论</strong><a href="#post-citation-6"><sup>[6]</sup></a>​，认为真核生物的<strong>线粒体</strong>来自于某种细菌的内共生，而<strong>叶绿体</strong>来自于某种<strong>蓝细菌</strong>（Cyanobacteria）的内共生；这一理论后续被罗伯特·施瓦茨（R. Schwartz）等人的一系列实验验证<a href="#post-citation-7"><sup>[7]</sup></a>​。基于此，从1981年开始，<span style="color: rgb(32, 33, 34); background-color: rgb(255, 255, 255); font-size: 16px">卡弗利尔-史密斯（T. </span>Cavalier-Smith<span style="color: rgb(32, 33, 34); background-color: rgb(255, 255, 255); font-size: 16px">）提出彻底重组</span>惠特克的五界体系<a href="#post-citation-8"><sup>[8]</sup></a>​<a href="#post-citation-9"><sup>[9]</sup></a>​，将原生生物拆分成<strong>色藻界</strong>（Chromista）、<strong>始虫界</strong>（Archezoa）和<strong>原生动物界</strong>（Protozoa）；他认为，始虫类代表了在线粒体内共生事件之前分支的真核生物<a href="#post-citation-8"><sup>[8]</sup></a>​，而色藻类包含了大多数光合原生生物，这些生物应当起源于同一次内共生事件<a href="#post-citation-9"><sup>[9]</sup></a>​。此外，他此时支持卡尔·乌斯等人提出的<strong>细菌</strong>（Bacteria）与<strong>古菌</strong>（Archaea）之间的重要区别，将原核界划分为<strong>真细菌界</strong>（Eubacteria）和<strong>古细菌界</strong>（Archaebacteria）<a href="#post-citation-10"><sup>[10]</sup></a>​。因此，他的新分类系统被成为<strong>八界系统</strong>。</p><p>1998年，<span style="color: rgb(32, 33, 34); background-color: rgb(255, 255, 255); font-size: 16px">卡弗利尔-史密斯认为原本的八界系统需要简化，并提出了</span><span style="color: rgb(32, 33, 34); background-color: rgb(255, 255, 255); font-size: 16px"><strong>六界系统</strong></span><a href="#post-citation-11"><sup>[11]</sup></a>​<span style="color: rgb(32, 33, 34); background-color: rgb(255, 255, 255); font-size: 16px">。首先，他意识到所谓的“</span>始虫<span style="color: rgb(32, 33, 34); background-color: rgb(255, 255, 255); font-size: 16px">”很可能是丢失了线粒体，而不是始终没有线粒体，所以将</span>始虫<span style="color: rgb(32, 33, 34); background-color: rgb(255, 255, 255); font-size: 16px">界合并入原生动物界等类群；其次，他不再承认细菌和古菌之间的根本性区别，因此提出原核生物的唯一界是</span><span style="color: rgb(32, 33, 34); background-color: rgb(255, 255, 255); font-size: 16px"><strong>细菌界</strong></span><span style="color: rgb(32, 33, 34); background-color: rgb(255, 255, 255); font-size: 16px">（</span>Bacteria<span style="color: rgb(32, 33, 34); background-color: rgb(255, 255, 255); font-size: 16px">）。另外，当时的</span><span style="color: rgb(32, 33, 34); background-color: rgb(255, 255, 255); font-size: 16px"><strong>分子系统发育学</strong></span><span style="color: rgb(32, 33, 34); background-color: rgb(255, 255, 255); font-size: 16px">已经有所发展，所谓“原生动物”已经基本被认定为</span><span style="color: rgb(32, 33, 34); background-color: rgb(255, 255, 255); font-size: 16px"><strong>并系群</strong></span><span style="color: rgb(32, 33, 34); background-color: rgb(255, 255, 255); font-size: 16px">，但卡弗利尔-史密斯并不接受完全的单系性原则</span><a href="#post-citation-12"><sup>[12]</sup></a>​<a href="#post-citation-13"><sup>[13]</sup></a>​<span style="color: rgb(32, 33, 34); background-color: rgb(255, 255, 255); font-size: 16px">，所以仍然保留了原生动物界。总之，六界系统是20世纪最后一个具有一定影响力的高等级分类系统，至今仍然能在一些场合看到；卡弗利尔-史密斯在去世之前也始终没有停止对该系统的修订</span><a href="#post-citation-12"><sup>[12]</sup></a>​<a href="#post-citation-14"><sup>[14]</sup></a>​<a href="#post-citation-15"><sup>[15]</sup></a>​<a href="#post-citation-16"><sup>[16]</sup></a>​<a href="#post-citation-17"><sup>[17]</sup></a>​<span style="color: rgb(32, 33, 34); background-color: rgb(255, 255, 255); font-size: 16px">（甚至后续又将古菌从细菌中独立，将系统重组为七界</span><a href="#post-citation-12"><sup>[12]</sup></a>​<span style="color: rgb(32, 33, 34); background-color: rgb(255, 255, 255); font-size: 16px">）。</span></p><h1>21世纪的真核生物分类学</h1><p>2000年，S. Baldauf 等人借助现代分子系统发育学工具，构建了一棵后来被广泛引用的真核生物系统发育树；该研究明确地指出，有多个此前定义的“界”<strong>并非单系群</strong>，而另一些重要的、被强烈支持的单系群此前却从未被识别<a href="#post-citation-18"><sup>[18]</sup></a>​。2004年，A. Simpson 等人在一篇综述中也指出，五界/六界等系统的流行是出于“将生物划分为几个简单群组的教学和修辞效用”，而不是因为其真正体现了系统发育关系；他们写到：“无论如何，<span style="color: rgb(46, 46, 46); background-color: rgb(255, 255, 255); font-size: 16px">大多数分类学者都认为，只有单系群应被归类为正式的分类群，这一原则绝对</span><span style="color: rgb(46, 46, 46); background-color: rgb(255, 255, 255); font-size: 16px"><strong>优先于便利性</strong></span>”<a href="#post-citation-19"><sup>[19]</sup></a>​。因此，五界/六界等分类系统是<strong>对真实系统发育信号的掩盖</strong>。但他们也指出，如果真的按照系统发育关系分配“界”，那可能需要“字面意义上的几十个界”，这对于很多实用性需求较高的场合来说是难以接受的；所以，他们认为合理的替代方案是“将真核生物划分为几个可能都是单系群的主要群体”<a href="#post-citation-19"><sup>[19]</sup></a>​。</p><p>2005年，以希纳·阿德尔（S. Adl）为首的<strong>国际原生生物学家协会</strong>发布了基于上述框架的真核生物新分类<a href="#post-citation-20"><sup>[20]</sup></a>​。该体系引入了<strong>超群</strong>（supergroup）的概念，表示系统发育框架下真核生物的<strong>主要单系群</strong>，其具体等级是任意的，但一般要求在门以上。据此，他们将真核生物划分为六个超群：<strong>古虫超群</strong>（Excavata）、<strong>变形超群</strong>（Amoebozoa）、<strong>后鞭毛超群</strong>（Opisthokonta）、<strong>根足超群</strong>（Rhizaria）、<strong>囊泡藻超群</strong>（Chromalveolata）和<strong>古质体超群</strong>（Archaeplastida）<a href="#post-citation-20"><sup>[20]</sup></a>​。</p><p>其中，古虫超群包含了许多被认为处于演化树基部的<strong>鞭毛虫</strong>，变形超群包含了大多数“变形虫形生物”和<strong>黏菌</strong>（此前黏菌一直被认为是一类真菌），后鞭毛超群包含了动物、真菌以及一些与它们关系密切的原生生物，根足超群包含了<strong>有孔虫</strong>（Foraminifera）、<strong>放射虫</strong>（Radiolaria）等原生生物，囊泡藻超群与色藻界的概念大致相当，古质体超群则替代了原本“植物界”的概念。（详见下文及各类群的分条目）</p><p>然而，在同一年，就有研究者对该体系产生了质疑，认为这六个超群中有一些不是单系群，还有一些并不是真核生物的主要群体<a href="#post-citation-21"><sup>[21]</sup></a>​。后续的研究证实，囊泡藻超群和古虫超群都不是单系群，而后鞭毛超群和根足超群的系统发育位置不足以支撑其为主要的真核超群<a href="#post-citation-22"><sup>[22]</sup></a>​<a href="#post-citation-23"><sup>[23]</sup></a>​。2007年，F. Burki 等人在研究中发现，根足超群、<strong>囊泡虫类</strong>（Alveolata，原属囊泡藻超群）和<strong>不等鞭毛类</strong>（Stramenopiles，原属囊泡藻超群）三个大类组成了一个新的超群，于是他用三者的首字母，将这个新超群命名为<strong>SAR超群</strong><a href="#post-citation-23"><sup>[23]</sup></a>​；后续研究表明，原属囊泡藻超群的<strong>定鞭藻</strong>（Haptophyta）、<strong>隐藻</strong>（Cryptophyta）和归属未定的<strong>中阳虫</strong>（Centroheliozoa）形成一个超群，即<strong>定隐超群</strong>（Hacrobia）<a href="#post-citation-24"><sup>[24]</sup></a>​。SAR超群-定隐超群的划分很快取代了根足超群-囊泡藻超群，成为了当时新的共识。</p><p>2009年，A. Simpson 等人将古虫的主体部分划分成了两个被强烈支持的新超群：<strong>后滴超群</strong>（Metamonada）和<strong>盘嵴超群</strong>（Discoba）<a href="#post-citation-25"><sup>[25]</sup></a>​；后续的研究基本确认了这两个新超群的单系性，但古虫本身却被认为是并系群<a href="#post-citation-26"><sup>[26]</sup></a>​。2013年，M. Brown 等人发现后鞭毛超群和两个小类群——<strong>短根虫</strong>（Breviata）与<strong>无根虫</strong>（Apusomonada）密切相关，于是他将这三者合在一起，定义了<strong>OBA超群</strong>（Obazoa），以取代原先的后鞭毛超群<a href="#post-citation-27"><sup>[27]</sup></a>​。</p><p>在超群被不断改进的基础上，也有人开始尝试解决各个超群之间的系统发育关系。2012年，希纳·阿德尔等人在超群之上确认了两个更大的类群：<strong>无定形生物</strong>（Amorphea，包括变形超群和OBA超群）和<strong>多貌生物</strong>（Diaphoretickes，当时认为包含古质体、定隐和SAR三个超群）<a href="#post-citation-28"><sup>[28]</sup></a>​。2015年，R. Derelle 等人在此基础上又提出了两个更大的类群：<strong>泛无定形生物</strong>（Opimoda，包含无定形生物和一些与之关系密切的鞭毛虫小类群）和<strong>泛多貌生物</strong>（Diphoda，包含多貌生物和盘嵴超群），并用以取代了传统的、有诸多问题的<strong>单鞭毛生物</strong>（U<span style="color: rgb(32, 33, 34); background-color: rgb(255, 255, 255); font-size: 16px">nikonta</span>）-<strong>双鞭毛生物</strong>（Bikonta）划分<a href="#post-citation-29"><sup>[29]</sup></a>​。</p><p>2016年，F. Burki 等人在一项新的研究中发现，定隐超群很可能不是单系群，而是包含了两个分支的并系群<a href="#post-citation-30"><sup>[30]</sup></a>​。其中一个分支以隐藻为核心，另包含一些与之关系密切的鞭毛虫，被称为<strong>隐藻超群</strong>（Cryptista）；另一个分支包含定鞭藻和中阳虫，被成为<strong>定鞭超群</strong>（Haptista）。这一观点基本被后续大多数研究所支持，定隐超群也自此被一分为二。该研究还认为，隐藻超群可能处在古质体超群的内部，但这一观点又被后续大多数研究否定<a href="#post-citation-30"><sup>[30]</sup></a>​<a href="#post-citation-31"><sup>[31]</sup></a>​。</p><p>2019年，J. Strassert 等人研究了一小类被称为<strong>网鞭虫</strong>（Telonemia）的原生生物的演化位置，并发现其可能是SAR超群的姊妹<a href="#post-citation-32"><sup>[32]</sup></a>​；这一观点一度成为了共识，并使得包含网鞭虫的<strong>TSAR超群</strong>取代了SAR超群的地位<a href="#post-citation-31"><sup>[31]</sup></a>​<a href="#post-citation-33"><sup>[33]</sup></a>​<a href="#post-citation-34"><sup>[34]</sup></a>​。但是，近两年的许多研究都不支持TSAR的单系性，而是认为网鞭虫是定鞭藻的姊妹，属于定鞭超群<a href="#post-citation-35"><sup>[35]</sup></a>​<a href="#post-citation-36"><sup>[36]</sup></a>​<a href="#post-citation-37"><sup>[37]</sup></a>​<a href="#post-citation-38"><sup>[38]</sup></a>​。目前，网鞭虫的位置仍有争议，需要进一步确认。</p><p>随着越来越多的“孤儿”原生生物谱系被纳入演化树中，新的超群被不断建立，部分旧的概念也被不断更新。2018年，M. Brown 等人发现三个原生生物小类群——<strong>翼形虫</strong>（Mantamonadea）、<strong>刚丝虫</strong>（Rigifilidea）和<strong>胶网虫</strong>（Collodictyonidea）之间有密切的关系，于是发表了<strong>CRuMs超群</strong>以容纳之<a href="#post-citation-39"><sup>[39]</sup></a>​。2022年，有人研究了<strong>微阳虫</strong>（<em>Microheliella</em>）的系统发育位置，并发现其是隐藻超群的姊妹<a href="#post-citation-40"><sup>[40]</sup></a>​；于是，他建立了新的、包含微阳虫的<strong>泛隐藻超群</strong>（Pancryptista）以容纳之，并取代原本隐藻超群的地位<a href="#post-citation-40"><sup>[40]</sup></a>​。</p><p>2025年和2026年，研究者又分别定义了目前为止，真核生物演化树上的最后两个超群——<strong>异貌超群</strong>（Disparia）<a href="#post-citation-37"><sup>[37]</sup></a>​<a href="#post-citation-41"><sup>[41]</sup></a>​和<strong>黏环超群</strong>（Glissogyra）<a href="#post-citation-38"><sup>[38]</sup></a>​。至此，这11个超群包含了所有已被正式描述且已知系统发育位置的真核生物。但在2026年9月，一项新的研究（目前尚未正式发表）表明，还有大量原生生物多样性未被描述，其中包括25个由环境基因序列识别出的新门<a href="#post-citation-42"><sup>[42]</sup></a>​。</p><h1>近两年关于真核生物系统发育的新进展</h1><p>2025年1月，G. Torruella 等人确认了二十多个此前研究不足的原生生物的转录组，并用它们构建出了一个更完善的真核生物系统发育树；这项研究支持了泛无定形生物的单系性，表明<strong>马拉维虫</strong>（Malawimonads）与<strong>锚鞭虫</strong>（Ancyromonads）很可能聚类，并提供了泛无定形生物的早期演化框架。<a href="#post-citation-36"><sup>[36]</sup></a>​</p><p>2025年1月，E. Yazaki 等人研究了一个此前关注极少，且从未有过分子数据的原生生物属<em>Glissandra</em><span style="color: rgb(27, 27, 27); background-color: rgb(255, 255, 255)">（</span><span style="color: rgb(27, 27, 27); background-color: rgb(255, 255, 255)"><strong>滑胞虫属</strong></span><span style="color: rgb(27, 27, 27); background-color: rgb(255, 255, 255)">），并发现它实际上代表了CRuMs超群中一个新的门级演化支；于是，它们建立了一个新的GRiDi类群作为CRuMs的亚群，并重新描述了该类群下的性状演化图景。</span><a href="#post-citation-43"><sup>[43]</sup></a>​</p><p>2025年3月，K. Williamson 等人利用线粒体蛋白数据集重建了真核生物演化树的根，并确认根的位置在泛多貌生物和泛无定形生物之间；这项研究还表明，真核生物的最近共同祖先（LECA）可能已经有<strong>典型的“古虫”形态</strong>。但是，部分被广泛支持的真核生物超群未能在这项研究中被恢复<a href="#post-citation-35"><sup>[35]</sup></a>​。</p><p>2025年8月，V. Zlatogursky 等人重点研究了部分“孤儿”原生生物谱系，并得出两个主要结论：（1）<strong>半鞭毛虫</strong>（Hemimastigophora）、<strong>流星虫</strong>（<em>Meteora</em>）、<strong>星云虫</strong>（Nebulidia）、<strong>小啃虫</strong>（Nibbleridia）四小群原生生物聚类成一个新的超群（文中命名为<span style="color: rgb(46, 46, 46); background-color: rgb(255, 255, 255); font-size: 16px">Promethea</span>）；（2）网鞭虫门是定鞭藻门的姊妹，属于定鞭超群，而不是SAR的姊妹。同时，网鞭虫门下一个新的属（<em>Microkorses</em>）也被发表。<a href="#post-citation-37"><sup>[37]</sup></a>​</p><p>2025年11月，M. Valt 等人描述了一个新的太阳虫属（<strong>变形阳虫属</strong>（<em>Solarion</em>），单种），并发现它是流星虫的姊妹；据此，他们将这两个属归入了一个新的门（<strong>天星虫门</strong>（Caelestes）），进而独立提出了与<span style="color: rgb(46, 46, 46); background-color: rgb(255, 255, 255); font-size: 16px">Promethea含义相同的新超群——异貌超群（</span>Disparia<span style="color: rgb(46, 46, 46); background-color: rgb(255, 255, 255); font-size: 16px">）。</span><a href="#post-citation-41"><sup>[41]</sup></a>​</p><p>2026年4月，X. Maurer-Alcalá 等人在预印本中提出，当前真核生物系统发育树的部分位置存在缺陷，并认为网鞭虫的姊妹群是<strong>皮胆虫</strong>（Picozoa，在大多数系统发育树中属于古质体类），两者聚类成一个叫<span style="color: rgb(80, 80, 80); background-color: rgb(255, 255, 255); font-size: 16px">Corbistoma的分支；此外，该研究也支持马拉维虫是锚鞭虫的姊妹。</span><a href="#post-citation-44"><sup>[44]</sup></a>​</p><p>2026年4月，R. <span style="color: rgb(51, 51, 51); background-color: rgb(255, 255, 255)">Leroy 等人在预印本中，基于一个独立的、丰富的数据集重建了真核生物的系统发育树；他们的结果强有力地支持网鞭虫是定鞭藻的姊妹群，并提出马拉维虫与锚鞭虫聚类成一个新超群——</span><span style="color: rgb(51, 51, 51); background-color: rgb(255, 255, 255)"><strong>黏环超群</strong></span><span style="color: rgb(51, 51, 51); background-color: rgb(255, 255, 255)">（</span><span style="color: rgb(25, 25, 25); background-color: rgb(255, 255, 255)">Glissogyra</span><span style="color: rgb(51, 51, 51); background-color: rgb(255, 255, 255)">），位于泛无定形生物的基部。</span><a href="#post-citation-38"><sup>[38]</sup></a>​</p><p>2026年8月，L.<span style="color: rgb(51, 51, 51); background-color: rgb(255, 255, 255)"> Tedersoo 等人在预印本中，基于大量环境基因组数据提出了25个未被描述的原生生物新门的名称，并对这些类群进行了初步研究和预测。</span><a href="#post-citation-42"><sup>[42]</sup></a>​</p><h1>生命时序编组的观点</h1><p>如上所述，学界对于真核生物高等级分类的处理方法基于“超群”这一林奈体系下的非正式等级；编组认为，虽然这套方法在过去的二十几年间成果显著，但依然不尽如人意。我们认为，<strong>多界的分类体系事实上是可行的</strong>，许多学者也提出过基于系统发育的、多界的而不是使用“超群”的真核生物分类框架<a href="#post-citation-45"><sup>[45]</sup></a>​<a href="#post-citation-46"><sup>[46]</sup></a>​<a href="#post-citation-47"><sup>[47]</sup></a>​<a href="#post-citation-48"><sup>[48]</sup></a>​；大多数“超群”应当<strong>直接处理为界</strong>，只有原先与色藻密切相关的定鞭超群和SAR超群，考虑到旧系统的影响和仍不明朗的系统发育，保留“超群”的称谓。另外，我们同意近几十年来藻类学界对于植物界的定义，即<strong>植物界与古质体类同义</strong>。</p><p>另外，OBA超群由于包含了动物、真菌两个传统界，其称谓也被保留。其下类群中，短根类和无根类分别被赋予界级；对于后鞭毛生物而言，可分为<strong>泛动物</strong>（Holozoa）和<strong>泛真菌</strong>（Holomycota）两个姊妹支，这两个类群可以被视为广义的动物界和真菌界，其下的各个不属于狭义动物/真菌界的类群不被视为独立界，而是被视为门。当然，狭义动物/真菌界的概念也被支持和保留。</p><p>综上所述，我们给出生命时序编组整理的的真核生物高等级分类体系，以及部分大类群的简要描述（未包含新近命名的一系列未被正式描述的类群）：</p><p><a href="/view-tree/d318b88c-e762-4f6d-907d-f062a940c66e" target="_blank" rel="noopener noreferrer nofollow">🌳 进化树：真核生物门级演化树</a></p><p><br></p><p>（注意：下表中，“·”表示系统发育上的包含关系，而不是分类群等级的高低）</p><p>· 真核生物 Eukaryota Whittaker &amp; Margulis, 1978</p><p>·· 暗核类 Scotokaryotes Cavalier-Smith, 1999</p><p>··· 后滴界 Metamonada Grassé, 1952</p><p>···· 厌氧变形虫门 Anaeramoebae Stairs et al., 2021</p><p>···· 副基体门 Parabasalia Honigberg, 1973</p><p>···· 前轴柱门 &nbsp;Preaxostyla Simpson, 2003</p><p>···· 拱形虫门 Fornicata Simpson, 2003</p><p>··· 泛无定形生物 Opimoda Derelle et al., 2015 </p><p>···· 黏环界 Glissogyra Leroy et al., 2026</p><p>····· 马拉维虫门 Malawimonada Cavalier-Smith, 2022 </p><p>····· 锚鞭虫门 Planomonada Cavalier-Smith, 2022</p><p>···· 异槽虫类 Podiata Cavalier-Smith, 2012</p><p>····· 异沟界 Crumalia Zmitrovich et al., 2022 = CRuMs supergroup Brown et al., 2018</p><p>······ 翼形虫门 Mantamonadea Zmitrovich et al., 2022</p><p>······ GRiDi类群 GRiDi group Yazaki et al., 2025</p><p>······· 滑胞虫门 Glissandria nom. ined.</p><p>······· 刚丝虫门 Rigifilidea Zmitrovich et al., 2022</p><p>······· 胶网虫门 Collodictyonida Speijer et al., 2015</p><p>····· 无定形生物 Amorphea Adl et al., 2012</p><p>······ 变形界 Amoebozoa Lühe, 1913</p><p>······· 真变形虫门 Tubulinea Smirnov et al., 2005</p><p>······· 异盘亚界 Divosa Tekle et al., 2022</p><p>········ 盘变形虫门 Discosea Cavalier-Smith et al., 2004</p><p>········ 异变形虫下界 Evosea Kang et al., 2017</p><p>········· 肤变形虫门 Cutosea Cavalier-Smith, 2016</p><p>········· 锥足总门 Conosa Cavalier-Smith, 1998</p><p>·········· 杂变形虫门 Variosea Cavalier-Smith et al., 2004</p><p>·········· 古变形虫门 Archamoebae Cavalier-Smith, 1998</p><p>·········· 黏菌门 Eumycetozoa Zopf, 1884 sensu Kang et al., 2017</p><p>······ OBA超群 Obazoa Brown et al., 2013</p><p>······· 短根界 Breviatae Tedersoo, 2017</p><p>········ 短根虫门 Breviata Tedersoo, 2017</p><p>······· 无根界 Apusozoa Cavalier-Smith, 1997</p><p>········ 无根虫门 Apusomonada Tedersoo, 2017</p><p>······· 后鞭毛生物 Opisthokonta Cavalier-Smith, 1987</p><p>········ 泛真菌类（广义真菌界）Holomycota Liu et al., 2009</p><p>········· 核形虫门 Nuclearida Tedersoo et al., 2018</p><p>········· 真菌界 Fungi Moore, 1980（下属类群省略）</p><p>········ 泛动物类（广义动物界）Holozoa Lang et al., 2002</p><p>········· 丸孢亚界 Teretosporea Torruella et al., 2015</p><p>·········· 中菌动物门 Mesomycetozoa Mendoza et al., 2002</p><p>·········· 多形壶菌门 Pluriformea Hehenberger et al., 2017</p><p>········· 囊掠虫门 Tunicaraptora nom. ined.</p><p>········· 蜷丝动物类 Filozoa Shalchian-Tabrizi et al., 2008</p><p>·········· 蜷丝球虫门 Filasterida Tedersoo, 2017</p><p>·········· 领鞭动物类 Choanozoa Brunet &amp; King, 2017</p><p>··········· 领鞭毛虫门 Choanoflagellata Kent, 1880</p><p>··········· 动物界 = 后生动物 Animalia L., 1758 = Metazoa Haeckel, 1874（下属类群省略）</p><p>·· 泛多貌生物 Diphoda Derelle et al., 2015</p><p>··· 盘嵴界 Discoba Hampl et al., 2009</p><p>···· 雅各巴虫门 Jakobida Cavalier-Smith, 1993</p><p>···· 筑波虫门 Tsukubamonada Tedersoo, 2017</p><p>····· 真盘嵴总门 Discicristata Cavalier-Smith, 1998</p><p>······ 渗养门 Heterolobosea Page &amp; Blanton, 1985</p><p>······ 眼虫门 Euglenozoa Cavalier-Smith, 1981</p><p>··· 多貌生物 Diaphoretickes Adl et al., 2012</p><p>···· CAM类群 CAM clade Yazaki et al., 2022</p><p>····· 古质体类 = 植物界 Archaeplastida Adl et al., 2005 = Plantae Haeckel, 1866</p><p>······ 红色植物亚界 Rhodoplantae Saunders &amp; Hommersand, 2004</p><p>······· 皮胆虫门 Picozoa Seenivasan et al., 2013</p><p>······· 红母虫门 Rhodelphidia Tikhonenkov et al., 2019</p><p>······· 红藻门 Rhodophyta Wettstein, 1922</p><p>······ 灰藻门 Glaucophyta Skuja, 1954</p><p>······ 绿色植物亚界 Viridiplantae Cavalier-Smith, 1981</p><p>······· 华藻门 Prasinodermophyta Li et al., 2020</p><p>······· 绿藻门 Chlorophyta Pascher, 1914</p><p>······· 链型植物门 Streptophyta Jeffrey, 1967</p><p>····· 隐藻界 Pancryptista Yazaki et al., 2022</p><p>······ 微阳虫门 Microheliellida Tedersoo, 2017</p><p>······ 隐藻亚界 Cryptista Cavalier-Smith, 1989</p><p>······· 颤虫门 Palpitomonada Zmitrovich et al., 2022</p><p>······· 下睫虫门 Katablepharidophyta Okamoto et al., 2005</p><p>······· 隐藻门 Cryptophyta Pascher, 1914</p><p>···· 异貌界 Disparia Valt et al., 2025 = <span style="color: rgb(46, 46, 46); background-color: rgb(255, 255, 255); font-size: 16px">Promethea </span>Zlatogursky et al., 2025</p><p>····· 贪噬亚界 Provora Tikhonenkov et al., 2022</p><p>······ 星云虫门 Nebulidia Tikhonenkov et al., 2022</p><p>······ 小啃虫门 Nibbleridia Tikhonenkov et al., 2022</p><p>····· 有肢亚界 Membrifera Valt et al., 2025</p><p>······ 天星虫门 Caelestes Valt et al., 2025</p><p>······ 半鞭毛虫门 Hemimastigophora Foissner, 1988</p><p>···· 定鞭超群 Haptista Cavalier-Smith, 2015</p><p>····· 中阳虫门 Centroheliozoa Dürrschmidt &amp; Patterson, 1987</p><p>····· 网鞭虫门 Telonemia Shalchian-Tabrizi et al., 2006</p><p>····· 定鞭藻门 Haptophyta Hibberd, 1976</p><p>···· SAR超群 SAR supergroup Burki et al., 2008</p><p>····· 根足亚界 Rhizaria Cavalier-Smith, 2002</p><p>······ 缕虫门 Filosa Cavalier-Smith &amp; Chao, 2003</p><p>······ 滑行虫门 Skiomonada nom. ined.</p><p>······ 粒网下界 Retaria Cavalier-Smith, 1999</p><p>······· 内黏菌门 Endomyxa Cavalier-Smith, 2002</p><p>······· 海粘虫门 Marimyxia Cavalier-Smith, 2018</p><p>······· 外网总门 Ectoreta Cavalier-Smith, 2018</p><p>········ 放射虫门 Radiolaria Cavalier-Smith, 1987</p><p>········ 有孔虫门 Foraminifera d''Orbigny, 1826</p><p>····· 囊泡虫亚界 Alveolata Cavalier-Smith, 1991</p><p>······ 勺钩虫门 Loeffelazoa nom. ined.</p><p>······ 纤毛虫门 Ciliophora Doflein, 1901</p><p>······ 单减虫门 Miozoa Cavalier-Smith, 1987</p><p>····· 不等鞭毛亚界 Stramenopiles Patterson, 1989</p><p>······ 扁沟门 Platysulcuzoa nom. ined.</p><p>······ 乳光门 Opalozoa Cavalier-Smith, 1991</p><p>······ 网体门 Sagenista Cavalier- Smith, 1995</p><p>······ 无面门 Kaonasha nom. ined.</p><p>······ 卵菌门 Oomycota Arx, 1967</p><p>······ 淡色藻门 Ochrophyta Cavalier-Smith, 1986</p><blockquote>对真核生物部分大类群的简要描述：<br>后滴界（Metamonada，即后滴超群）：原“古虫”的一支，一大类厌氧的真核生物，绝大多数是单细胞鞭毛虫，一部分自由生活，另一部分是动物的共生体或寄生虫。其线粒体退化，取而代之的是氢小体（hydrogenosome）、线裂体（mitosome）等负责厌氧呼吸的线粒体相关细胞器（MROs）。<br>盘嵴界（Discoba，即盘嵴超群）：原“古虫”的一支，主要由自由生活的单细胞鞭毛虫（多数双鞭毛）组成，其核心类群具有盘状的线粒体嵴，故此得名。该类群多样性很高，主要由自由生活的鞭毛虫、光合作用者（眼虫亚纲）与寄生虫（动质体纲）组成，彼此之间缺乏显著的形态共性。<br>黏环界（Glissogyra，即黏环超群）：一小群异养的单细胞双鞭毛虫，目前仅有两个门类十几个属。细胞运动通常表现为附着在基质上滑行，轨迹经常呈现环状，故此得名。<br>异沟界（Crumalia，即CRuMs超群）：一小群食菌性异养单细胞生物，包括了有鞭毛的（翼形虫门、滑胞虫门、胶网虫门）与具有细长根状伪足的（刚丝虫门），大部分有伪足。其他比较明显的形态特征包括细胞膜下有一层坚韧的表膜，以及通常很明显的腹沟。名称来源于该类群的异名Varisulca（Vari(多样的)-sulca(沟)）。<br>变形界（Amoebozoa，即变形超群）：通称变形虫，一大类常见的异养变形虫形生物，拥有伪足，部分类群拥有鞭毛；大多数是典型的单细胞生物，部分类群可以形成多细胞的子实体（如黏菌门）。大部分变形虫细胞膜外无覆盖物，但也有部分有壳（主要在表壳目）；绝大多数变形虫是自由生活的，小部分是专性或机会性寄生虫。<br>OBA超群（Obazoa）：包含了动物、真菌以及部分与它们关系密切的原生生物。三个子类群中，短根虫和无根虫都是拥有双鞭毛的变形虫形生物，前者（兼性）厌氧，后者伪足不明显；后鞭毛生物（或其单细胞配子）仅有一条后鞭毛，其下多数类群都具有不同程度的多细胞性。<br>隐藻界（Pancryptista，即泛隐藻超群）：包含了隐藻以及部分与之关系密切的异养单细胞原生生物，除了基部的微阳虫是无鞭毛的太阳虫外，其他类群都拥有两根鞭毛。除了隐藻纲是光合藻类以外，其他类群基本都是自由生活的异养生物。<br>植物界（Plantae）：近几十年学界主流的观点认为，植物界的范围应与古质体超群一致。据此，植物界包含了一大类主要的光合生物和少数异养生物，其共同祖先被认为内共生了蓝细菌，并由此获得了光合能力。下属类群包括陆地植物以及部分传统意义上的藻类（如绿藻、红藻），以及部分被认为丢失了光合能力的异养鞭毛虫（皮胆虫、红母虫）。<br>异貌界（Disparia = Promethea，即异貌超群）：一小群异养单细胞生物，大多数是鞭毛虫，以捕食其他真核生物为生（天星虫门除外）。名称来自Disparia，意在表明该类群是多貌生物的一支，且其下各门之间形态差异甚大。<br>定鞭超群（Haptista）：由异养原生生物和藻类组成的类群。其下，中阳虫门是一类主要的太阳虫，无鞭毛且拥有标志性的轴伪足，异养或混合营养；定鞭藻门是一支主要的藻类，通常拥有两根鞭毛和一根类似于鞭毛的、标志性的定鞭，其下核心类群球石藻还拥有钙质外壳。网鞭虫门可能属于该类群。<br>SAR超群（SAR supergroup）：一大类极为多样的原生生物，名称来自三个亚群的首字母。其中，根足亚界主要由自由的异养生物构成，许多类群都能产生根状或网状伪足；囊泡虫亚界的细胞膜下存在皮质囊泡，主要包括纤毛虫、顶复虫和甲藻三大类；不等鞭毛亚界的鞭毛上存在三分、管状、硬质的短茸，核心类群是卵菌门和淡色藻门。</blockquote><p><br></p>','发布文章','2026-09-07T12:44:52.761Z','bb3d1539-cecb-4133-8913-c5e8569b6366','{"cards":[]}','[{"number":1,"text":"Singer C J. A short history of biology: a general i