INSERT INTO "published_trees" ("id","creator_id","kind","title","description","document_json","node_count","license","version","created_at","updated_at","deleted_at","public_id","tags_json","change_note","fork_enabled","contribution_enabled","forked_from_tree_id","references_text","image_credits_text","platform_recommended","platform_reviewed_at","platform_reviewed_by","visibility") VALUES('b53a0034-c7f5-43fb-83f8-3cdd46e2a314','50dd0d9e-c584-448c-a10b-167bca6d6346','USER','生命起源（Fork）','生命起源','{"layout":"logicalStructure","evolution":{"nodeLineStyle":true,"hideInternalNames":false,"alignLeavesRight":false},"root":{"data":{"uid":"8612a8a4-6c3e-49ec-8f82-e3feacdf9414","text":"生命起源","expand":true,"hyperlink":"","hyperlinkTitle":"","image":"","imageTitle":"","color":"#000000","fillColor":"#ffffff","borderColor":"#ffffff","lineColor":"#000000","borderWidth":0,"borderDasharray":"","fontSize":15,"fontWeight":"normal","shape":"rectangle"},"children":[{"data":{"uid":"6982b9f1-1b18-4a52-ae0f-dd99054011a6","text":"碱性热液喷口理论","expand":true,"hyperlink":"","hyperlinkTitle":"","image":"","imageTitle":"","color":"#000000","fillColor":"#ffffff","borderColor":"#ffffff","lineColor":"#000000","borderWidth":0,"borderDasharray":"","fontSize":15,"fontWeight":"normal","shape":"rectangle"},"children":[{"data":{"uid":"17d39ca2-f0e7-4896-9201-b31e41709a29","text":"生命起源于深海碱性热液喷口（alkaline hydrothermal vents）。","expand":true,"hyperlink":"","hyperlinkTitle":"","image":"","imageTitle":"","color":"#000000","fillColor":"#ffffff","borderColor":"#ffffff","lineColor":"#000000","borderWidth":0,"borderDasharray":"","fontSize":15,"fontWeight":"normal","shape":"rectangle"},"children":[]},{"data":{"uid":"22523271-ae1c-4e0a-969e-129bee9df4bd","text":"1988-1989年，英国地质学家罗素（Michael Russell）预测了不同于“黑烟囱”（酸性、高温）的另一种热液系统：碱性热液喷口（白烟囱）——碱性（pH 9–11）、低温（<90°C）、富含H₂和CH₄。而在2000年，Deborah Kelley等在中大西洋脊发现“失落之城”（Lost City Hydrothermal Field，LCHF）——与Russell在 1988年预测高度吻合。","expand":true,"hyperlink":"","hyperlinkTitle":"","image":"","imageTitle":"","color":"#000000","fillColor":"#ffffff","borderColor":"#ffffff","lineColor":"#000000","borderWidth":0,"borderDasharray":"","fontSize":15,"fontWeight":"normal","shape":"rectangle"},"children":[]}]},{"data":{"uid":"19af4b36-a412-4e6b-aefe-da52097a1c00","text":"铁-硫世界","expand":true,"hyperlink":"","hyperlinkTitle":"","image":"","imageTitle":"","color":"#000000","fillColor":"#ffffff","borderColor":"#ffffff","lineColor":"#000000","borderWidth":0,"borderDasharray":"","fontSize":15,"fontWeight":"normal","shape":"rectangle"},"children":[]},{"data":{"uid":"c24dee51-66dd-4cd4-85c8-321816b601c8","text":"自催化集","expand":true,"hyperlink":"","hyperlinkTitle":"","image":"","imageTitle":"","color":"#000000","fillColor":"#ffffff","borderColor":"#ffffff","lineColor":"#000000","borderWidth":0,"borderDasharray":"","fontSize":15,"fontWeight":"normal","shape":"rectangle"},"children":[{"data":{"uid":"2cae5adb-2af2-4fa0-98a6-35daa246d4cc","text":"有机物逐步合成，形成一个催化网络。也就是反应的产物可以作为反应的催化剂，形成一个闭环。这就是自催化网络","expand":true,"hyperlink":"","hyperlinkTitle":"","image":"","imageTitle":"","color":"#000000","fillColor":"#ffffff","borderColor":"#ffffff","lineColor":"#000000","borderWidth":0,"borderDasharray":"","fontSize":15,"fontWeight":"normal","shape":"rectangle"},"children":[]}]},{"data":{"uid":"e89b3646-42cd-4f0a-ba93-5cac4f20f7a8","text":"组合世界假说","expand":true,"hyperlink":"","hyperlinkTitle":"","image":"","imageTitle":"","color":"#000000","fillColor":"#ffffff","borderColor":"#ffffff","lineColor":"#000000","borderWidth":0,"borderDasharray":"","fontSize":15,"fontWeight":"normal","shape":"rectangle"},"children":[]},{"data":{"uid":"64ad7181-3146-44bc-b6f6-f55bf138fec4","text":"硫酯世界","expand":true,"hyperlink":"","hyperlinkTitle":"","image":"","imageTitle":"","color":"#000000","fillColor":"#ffffff","borderColor":"#ffffff","lineColor":"#000000","borderWidth":0,"borderDasharray":"","fontSize":15,"fontWeight":"normal","shape":"rectangle"},"children":[{"data":{"uid":"b4237660-2cd7-4430-9365-10c0ca4c701f","text":"硫酯激活氨基酸并选择性连接到RNA，形成氨酰-RNA，随后催化肽键形成。","expand":true,"hyperlink":"","hyperlinkTitle":"","image":"","imageTitle":"","color":"#000000","fillColor":"#ffffff","borderColor":"#ffffff","lineColor":"#000000","borderWidth":0,"borderDasharray":"","fontSize":15,"fontWeight":"normal","shape":"rectangle"},"children":[]}]},{"data":{"uid":"616c8138-8307-47d9-a81a-fe1311595565","text":"RNA世界假说","expand":true,"hyperlink":"","hyperlinkTitle":"","image":"","imageTitle":"","color":"#000000","fillColor":"#ffffff","borderColor":"#ffffff","lineColor":"#000000","borderWidth":0,"borderDasharray":"","fontSize":15,"fontWeight":"normal","shape":"rectangle"},"children":[{"data":{"uid":"07a884f0-eb47-4de6-ae98-d509d8111150","text":"无序的生命物质开始向有序生命物质的转变。从而产生了第一个能够维持自身代谢的生命系统。","expand":true,"hyperlink":"","hyperlinkTitle":"","image":"","imageTitle":"","color":"#000000","fillColor":"#ffffff","borderColor":"#ffffff","lineColor":"#000000","borderWidth":0,"borderDasharray":"","fontSize":15,"fontWeight":"normal","shape":"rectangle"},"children":[]}]},{"data":{"uid":"37f92cdd-5cbc-48f6-822f-7969413eed3e","text":"FUCA","expand":true,"hyperlink":"","hyperlinkTitle":"","image":"","imageTitle":"","color":"#000000","fillColor":"#ffffff","borderColor":"#ffffff","lineColor":"#000000","borderWidth":0,"borderDasharray":"","fontSize":15,"fontWeight":"normal","shape":"rectangle"},"children":[{"data":{"uid":"96036003-746a-48b2-80b8-0784c6206508","text":"FUCA标志着生命不仅仅有代谢，而且开始有合成蛋白质的能力，标志着遗传编码的初步成型。RNA开始催化氨基酸连接成短肽，并形成翻译系统的雏形","expand":true,"hyperlink":"","hyperlinkTitle":"","image":"","imageTitle":"","color":"#000000","fillColor":"#ffffff","borderColor":"#ffffff","lineColor":"#000000","borderWidth":0,"borderDasharray":"","fontSize":15,"fontWeight":"normal","shape":"rectangle"},"children":[]}]},{"data":{"uid":"1857b44a-231d-4b40-8cfa-2722b1f6c1fb","text":"病毒世界","expand":true,"hyperlink":"","hyperlinkTitle":"","image":"","imageTitle":"","color":"#000000","fillColor":"#ffffff","borderColor":"#ffffff","lineColor":"#000000","borderWidth":0,"borderDasharray":"","fontSize":15,"fontWeight":"normal","shape":"rectangle"},"children":[{"data":{"uid":"b35c2be3-4629-4a5b-b4d8-5765d5b15592","text":"既是细胞基因的祖先，也是现代病毒的起源。","expand":true,"hyperlink":"","hyperlinkTitle":"","image":"","imageTitle":"","color":"#000000","fillColor":"#ffffff","borderColor":"#ffffff","lineColor":"#000000","borderWidth":0,"borderDasharray":"","fontSize":15,"fontWeight":"normal","shape":"rectangle"},"children":[]}]},{"data":{"uid":"eaa455c8-db72-4d2d-8e94-bd639723b0fb","text":"LUCA","expand":true,"hyperlink":"","hyperlinkTitle":"","image":"","imageTitle":"","color":"#000000","fillColor":"#ffffff","borderColor":"#ffffff","lineColor":"#000000","borderWidth":0,"borderDasharray":"","fontSize":15,"fontWeight":"normal","shape":"rectangle"},"children":[{"data":{"uid":"846d95ac-6435-4570-8e6f-0005b7c5dd54","text":"现存所有生命（真细菌、古细菌、真核生物）的最近共同祖先，","expand":true,"hyperlink":"","hyperlinkTitle":"","image":"","imageTitle":"","color":"#000000","fillColor":"#ffffff","borderColor":"#ffffff","lineColor":"#000000","borderWidth":0,"borderDasharray":"","fontSize":15,"fontWeight":"normal","shape":"rectangle"},"children":[]},{"data":{"uid":"87b99b4f-981f-49d3-bd5b-337835eb81f3","text":"分庭抗礼","expand":true,"hyperlink":"","hyperlinkTitle":"","image":"/media/dac7c93c2f7580cad9d3b6a09bd431eed6294f1fba80e6f0ed2a88cfa245f9cd","imageTitle":"XMind 导入图片","color":"#000000","fillColor":"#ffffff","borderColor":"#ffffff","lineColor":"#000000","borderWidth":0,"borderDasharray":"","fontSize":15,"fontWeight":"normal","shape":"rectangle","imageSize":{"width":375,"height":259,"custom":false}},"children":[{"data":{"uid":"96e38e1a-9b84-4551-b514-345d3f3bc94d","text":"古细菌","expand":true,"hyperlink":"","hyperlinkTitle":"","image":"","imageTitle":"","color":"#000000","fillColor":"#ffffff","borderColor":"#ffffff","lineColor":"#000000","borderWidth":0,"borderDasharray":"","fontSize":15,"fontWeight":"normal","shape":"rectangle"},"children":[]},{"data":{"