INSERT INTO "tree_revisions" ("tree_id","version","title","description","document_json","node_count","license","created_at","created_by","tags_json","change_note","fork_enabled","contribution_enabled","references_text","image_credits_text") VALUES('b53a0034-c7f5-43fb-83f8-3cdd46e2a314',1,'生命起源（Fork）','生命起源','{"layout":"logicalStructure","evolution":{"nodeLineStyle":true,"hideInternalNames":false,"alignLeavesRight":false},"root":{"data":{"uid":"8612a8a4-6c3e-49ec-8f82-e3feacdf9414","text":"生命起源","expand":true,"hyperlink":"","hyperlinkTitle":"","image":"","imageTitle":"","color":"#000000","fillColor":"#ffffff","borderColor":"#ffffff","lineColor":"#000000","borderWidth":0,"borderDasharray":"","fontSize":15,"fontWeight":"normal","shape":"rectangle"},"children":[{"data":{"uid":"6982b9f1-1b18-4a52-ae0f-dd99054011a6","text":"碱性热液喷口理论","expand":true,"hyperlink":"","hyperlinkTitle":"","image":"","imageTitle":"","color":"#000000","fillColor":"#ffffff","borderColor":"#ffffff","lineColor":"#000000","borderWidth":0,"borderDasharray":"","fontSize":15,"fontWeight":"normal","shape":"rectangle"},"children":[{"data":{"uid":"17d39ca2-f0e7-4896-9201-b31e41709a29","text":"生命起源于深海碱性热液喷口（alkaline hydrothermal vents）。","expand":true,"hyperlink":"","hyperlinkTitle":"","image":"","imageTitle":"","color":"#000000","fillColor":"#ffffff","borderColor":"#ffffff","lineColor":"#000000","borderWidth":0,"borderDasharray":"","fontSize":15,"fontWeight":"normal","shape":"rectangle"},"children":[]},{"data":{"uid":"22523271-ae1c-4e0a-969e-129bee9df4bd","text":"1988-1989年，英国地质学家罗素（Michael Russell）预测了不同于“黑烟囱”（酸性、高温）的另一种热液系统：碱性热液喷口（白烟囱）——碱性（pH 9–11）、低温（<90°C）、富含H₂和CH₄。而在2000年，Deborah Kelley等在中大西洋脊发现“失落之城”（Lost City Hydrothermal Field，LCHF）——与Russell在 1988年预测高度吻合。","expand":true,"hyperlink":"","hyperlinkTitle":"","image":"","imageTitle":"","color":"#000000","fillColor":"#ffffff","borderColor":"#ffffff","lineColor":"#000000","borderWidth":0,"borderDasharray":"","fontSize":15,"fontWeight":"normal","shape":"rectangle"},"children":[]}]},{"data":{"uid":"19af4b36-a412-4e6b-aefe-da52097a1c00","text":"铁-硫世界","expand":true,"hyperlink":"","hyperlinkTitle":"","image":"","imageTitle":"","color":"#000000","fillColor":"#ffffff","borderColor":"#ffffff","lineColor":"#000000","borderWidth":0,"borderDasharray":"","fontSize":15,"fontWeight":"normal","shape":"rectangle"},"children":[]},{"data":{"uid":"c24dee51-66dd-4cd4-85c8-321816b601c8","text":"自催化集","expand":true,"hyperlink":"","hyperlinkTitle":"","image":"","imageTitle":"","color":"#000000","fillColor":"#ffffff","borderColor":"#ffffff","lineColor":"#000000","borderWidth":0,"borderDasharray":"","fontSize":15,"fontWeight":"normal","shape":"rectangle"},"children":[{"data":{"uid":"2cae5adb-2af2-4fa0-98a6-35daa246d4cc","text":"有机物逐步合成，形成一个催化网络。也就是反应的产物可以作为反应的催化剂，形成一个闭环。这就是自催化网络","expand":true,"hyperlink":"","hyperlinkTitle":"","image":"","imageTitle":"","color":"#000000","fillColor":"#ffffff","borderColor":"#ffffff","lineColor":"#000000","borderWidth":0,"borderDasharray":"","fontSize":15,"fontWeight":"normal","shape":"rectangle"},"children":[]}]},{"data":{"uid":"e89b3646-42cd-4f0a-ba93-5cac4f20f7a8","text":"组合世界假说","expand":true,"hyperlink":"","hyperlinkTitle":"","image":"","imageTitle":"","color":"#000000","fillColor":"#ffffff","borderColor":"#ffffff","lineColor":"#000000","borderWidth":0,"borderDasharray":"","fontSize":15,"fontWeight":"normal","shape":"rectangle"},"children":[]},{"data":{"uid":"64ad7181-3146-44bc-b6f6-f55bf138fec4","text":"硫酯世界","expand":true,"hyperlink":"","hyperlinkTitle":"","image":"","imageTitle":"","color":"#000000","fillColor":"#ffffff","borderColor":"#ffffff","lineColor":"#000000","borderWidth":0,"borderDasharray":"","fontSize":15,"fontWeight":"normal","shape":"rectangle"},"children":[{"data":{"uid":"b4237660-2cd7-4430-9365-10c0ca4c701f","text":"硫酯激活氨基酸并选择性连接到RNA，形成氨酰-RNA，随后催化肽键形成。","expand":true,"hyperlink":"","hyperlinkTitle":"","image":"","imageTitle":"","color":"#000000","fillColor":"#ffffff","borderColor":"#f