INSERT INTO "tree_contributions" ("id","target_tree_id","contributor_id","base_version","title","description","document_json","node_count","license","tags_json","change_note","fork_enabled","contribution_enabled","status","review_note","created_at","updated_at","reviewed_at","reviewed_by","references_text","image_credits_text") VALUES('cd71fc94-3b6c-448b-acb5-9aa4575d7d66','ecfa8cf8-d58e-4159-bd45-d4e40c37314d','50dd0d9e-c584-448c-a10b-167bca6d6346',4,'生命起源','生命起源','{"layout":"logicalStructure","evolution":{"nodeLineStyle":true,"hideInternalNames":false,"alignLeavesRight":false},"root":{"data":{"uid":"8612a8a4-6c3e-49ec-8f82-e3feacdf9414","text":"生命起源","expand":true,"hyperlink":"","hyperlinkTitle":"","image":"","imageTitle":"","color":"#000000","fillColor":"#ffffff","borderColor":"#ffffff","lineColor":"#000000","borderWidth":0,"borderDasharray":"","fontSize":15,"fontWeight":"normal","shape":"rectangle"},"children":[{"data":{"uid":"6982b9f1-1b18-4a52-ae0f-dd99054011a6","text":"碱性热液喷口理论","expand":true,"hyperlink":"","hyperlinkTitle":"","image":"","imageTitle":"","color":"#000000","fillColor":"#ffffff","borderColor":"#ffffff","lineColor":"#000000","borderWidth":0,"borderDasharray":"","fontSize":15,"fontWeight":"normal","shape":"rectangle"},"children":[{"data":{"uid":"17d39ca2-f0e7-4896-9201-b31e41709a29","text":"生命起源于深海碱性热液喷口（alkaline hydrothermal vents）。","expand":true,"hyperlink":"","hyperlinkTitle":"","image":"","imageTitle":"","color":"#000000","fillColor":"#ffffff","borderColor":"#ffffff","lineColor":"#000000","borderWidth":0,"borderDasharray":"","fontSize":15,"fontWeight":"normal","shape":"rectangle"},"children":[]},{"data":{"uid":"95268786-9521-47a3-945a-700105cbc739","text":"1988-1989年，英国地质学家罗素（Michael Russell）预测了不同于“黑烟囱”（酸性、高温）的另一种热液系统：碱性热液喷口（白烟囱）——碱性（pH 9–11）、低温（<90°C）、富含H₂和CH₄。而在2000年，Deborah Kelley等在中大西洋脊发现“失落之城”（Lost City Hydrothermal Field，LCHF）——与Russell在 1988年预测高度吻合。","expand":true,"hyperlink":"","hyperlinkTitle":"","image":"","imageTitle":"","color":"#000000","fillColor":"#ffffff","borderColor":"#ffffff","lineColor":"#000000","borderWidth":0,"borderDasharray":"","fontSize":15,"fontWeight":"normal","shape":"rectangle"},"children":[]},{"data":{"uid":"8b9784d1-e0e7-454c-99b4-9f93fe8093dd","text":"在此基础上，关于生命起源的新理论——碱性热液喷口理论（Alkaline Hydrothermal Vents Hypothesis)磅礴发展，并迅速占据主流。","expand":true,"hyperlink":"","hyperlinkTitle":"","image":"","imageTitle":"","color":"#000000","fillColor":"#ffffff","borderColor":"#ffffff","lineColor":"#000000","borderWidth":0,"borderDasharray":"","fontSize":15,"fontWeight":"normal","shape":"rectangle"},"children":[]},{"data":{"uid":"bc17edc9-100a-42d7-8316-b7e3b2608b12","text":"碱性热液喷口理论是生命起源领域的一个关键模型，其主张生命起源于深海碱性热液喷口（alkaline hydrothermal vents）。","expand":true,"hyperlink":"","hyperlinkTitle":"","image":"","imageTitle":"","color":"#000000","fillColor":"#ffffff","borderColor":"#ffffff","lineColor":"#000000","borderWidth":0,"borderDasharray":"","fontSize":15,"fontWeight":"normal","shape":"rectangle"},"children":[]}]},{"data":{"uid":"19af4b36-a412-4e6b-aefe-da52097a1c00","text":"铁-硫世界","expand":true,"hyperlink":"","hyperlinkTitle":"","image":"","imageTitle":"","color":"#000000","fillColor":"#ffffff","borderColor":"#ffffff","lineColor":"#000000","borderWidth":0,"borderDasharray":"","fontSize":15,"fontWeight":"normal","shape":"rectangle"},"children":[]},{"data":{"uid":"c24dee51-66dd-4cd4-85c8-321816b601c8","text":"自催化集","expand":true,"hyperlink":"","hyperlinkTitle":"","image":"","imageTitle":"","color":"#000000","fillColor":"#ffffff","borderColor":"#ffffff","lineColor":"#000000","borderWidth":0,"borderDasharray":"","fontSize":15,"fontWeight":"normal","shape":"rectangle"},"children":[{"data":{"uid":"2cae5adb-2af2-4fa0-98a6-35daa246d4cc","text":"有机物逐步合成，形成一个催化网络。也就是反应的产物可以作为反应的催化剂，形成一个闭环。这就是自催化网络","expand":true,"hyperlink":"","hyperlinkTitle":"","image":"","imageTitle":"","color":"#000000","fillColor":"#ffffff","borderColor":"#ffffff","lineColor":"#000000","borderWidth":0,"borderDasharray":"","fontSize":15,"fontWeight":"normal","shape":"rectangle"},"children":[]}]},{"data":{"uid":"e89b3646-42cd-4f0a-ba93-5cac4f20f7a8","text":"组合世界假说","expand":true,"hyperlink":"","hyperlinkTitle":"","image":"","imageTitle":"","color":"#000000","fillColor":"#ffffff","borderColor":"#ffffff","lineColor":"#000000","borderWidth":0,"borderDasharray":"","fontSize":15,"fontWeight":"normal","shape":"rectangle"},"children":[]},{"data":{"uid":"64ad7181-3146-44bc-b6f6-f55bf138fec4","text":"硫酯世界","expand":true,"hyperlink":"","hyperlinkTitle":"","image":"","imageTitle":"","color":"#000000","fillColor":"#ffffff","borderColor":"#ffffff","lineColor":"#000000","borderWidth":0,"borderDasharray":"","fontSize":15,"fontWeight":"normal","shape":"rectangle"},"children":[{"data":{"uid":"b4237660-2cd7-4430-9365-10c0ca4c701f","text":"硫酯激活氨基酸并选择性连接到RNA，形成氨酰-RNA，随后催化肽键形成。","expand":true,"hyperlink":"","hyperlinkTitle":"","image":"","imageTitle":"","color":"#000000","fillColor":"#ffffff","borderColor":"#ffffff","lineColor":"#000000","borderWidth":0,"borderDasharray":"","fontSize":15,"fontWeight":"normal","shape":"rectangle"},"children":[]}]},{"data":{"uid":"616c8138-8307-47d9-a81a-fe1311595565","text":"RNA世界假说","expand":true,"hyperlink":"","hyperlinkTitle":"","image":"","imageTitle":"","color":"#000000","fillColor":"#ffffff","borderColor":"#ffffff","lineColor":"#000000","borderWidth":0,"borderDasharray":"","fontSize":15,"fontWeight":"normal","shape":"rectangle"},"children":[{"data":{"uid":"07a884f0-eb47-4de6-ae98-d509d8111150","text":"无序的生命物质开始向有序生命物质的转变。从而产生了第一个能够维持自身代谢的生命系统。","expand":true,"hyperlink":"","hyperlinkTitle":"","image":"","imageTitle":"","color":"#000000","fillColor":"#ffffff","borderColor":"#ffffff","lineColor":"#000000","borderWidth":0,"borderDasharray":"","fontSize":15,"fontWeight":"normal","shape":"rectangle"},"children":[]}]},{"data":{"uid":"37f92cdd-5cbc-48f6-822f-7969413eed3e","text":"FUCA","expand":true,"hyperlink":"","hyperlinkTitle":"","image":"","imageTitle":"","color":"#000000","